          <group>
            {/* Segment [AB] — fil portant le courant I */}
            <Cylinder args={[0.04, 0.04, visualHalfLength * 2, 16]} position={[0, 0, 0]}>
              <meshStandardMaterial color="#06b6d4" emissive="#06b6d4" emissiveIntensity={0.5} />
            </Cylinder>

            {/* Glow around wire */}
            <Cylinder args={[0.12, 0.12, visualHalfLength * 2, 16]} position={[0, 0, 0]}>
              <meshBasicMaterial color="#06b6d4" transparent opacity={0.1} />
            </Cylinder>

            {/* Labels A and B (hide if infinite) */}
            {!isInfinite && (
              <>
                <Html position={[0, -halfLength - 0.4, 0]} center>
                  <div className="text-cyan-400 font-black text-sm drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">A</div>
                </Html>
                <Html position={[0, halfLength + 0.4, 0]} center>
                  <div className="text-cyan-400 font-black text-sm drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">B</div>
                </Html>
              </>
            )}

            {/* Current arrow I */}
            <mesh position={[0, (isInfinite ? 4.0 : halfLength + 0.15), 0]} rotation={[currentDirection === -1 ? Math.PI : 0, 0, 0]}>
              <coneGeometry args={[0.1, 0.35, 8]} />
              <meshBasicMaterial color="#06b6d4" />
            </mesh>
            <Html position={[-0.5, (isInfinite ? 4.0 : halfLength + 0.3), 0]} center>
              <div className="text-cyan-400 font-bold text-xs drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">I</div>
            </Html>

            {/* Point M */}
            <Sphere args={[0.15, 16, 16]} position={[mX, mY, 0]}>
              <meshStandardMaterial color="#f59e0b" emissive="#d97706" emissiveIntensity={0.8} />
            </Sphere>
            <Html position={[mX + 0.35, mY + 0.35, 0]} center>
              <div className="text-amber-400 font-black text-sm drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">M</div>
            </Html>

            {/* Distance d (horizontal line from wire to M) */}
            <Line points={[[0, mY, 0], [mX, mY, 0]]} color="#f472b6" lineWidth={2} dashed dashSize={0.15} gapSize={0.1} />
            <Html position={[mX / 2, mY - 0.35, 0]} center>
              <div className="text-pink-400 font-bold text-xs italic drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">d</div>
            </Html>

            {/* r lines from segment endpoints to M (hide if infinite) */}
            {!isInfinite && (
              <>
                <Line points={[[0, segBot, 0], [mX, mY, 0]]} color="#94a3b8" lineWidth={1} transparent opacity={0.4} />
                <Line points={[[0, segTop, 0], [mX, mY, 0]]} color="#94a3b8" lineWidth={1} transparent opacity={0.4} />
              </>
            )}

            {/* Angle Filled Slices α₁ and α₂ (hide if infinite) */}
            {!isInfinite && (
              <>
                <AngleSlice center={[mX, mY, 0]} radius={0.7} color="#0ea5e9" isTop={false} distance={distance} yRel={yRelBot} label="α₁" />
                <AngleSlice center={[mX, mY, 0]} radius={0.9} color="#14b8a6" isTop={true} distance={distance} yRel={yRelTop} label="α₂" />
              </>
            )}

            {/* Field Line (Circle) passing through M */}
            <group position={[0, mY, 0]}>
              <Line points={fieldLinePoints} color="#10b981" lineWidth={1.5} transparent opacity={0.3} dashed dashSize={0.2} gapSize={0.2} />
              {/* Directional arrows on the field line */}
              <mesh position={[0, 0, distance]} rotation={[0, 0, Math.PI / 2 * currentDirection]}> {/* Pointing -X or +X */}
                <coneGeometry args={[0.08, 0.25, 8]} />
                <meshBasicMaterial color="#10b981" transparent opacity={0.5} />
              </mesh>
              <mesh position={[-distance, 0, 0]} rotation={[Math.PI / 2 * currentDirection, 0, 0]}> {/* Pointing +Z or -Z */}
                <coneGeometry args={[0.08, 0.25, 8]} />
                <meshBasicMaterial color="#10b981" transparent opacity={0.5} />
              </mesh>
              <mesh position={[0, 0, -distance]} rotation={[0, 0, -Math.PI / 2 * currentDirection]}> {/* Pointing +X or -X */}
                <coneGeometry args={[0.08, 0.25, 8]} />
                <meshBasicMaterial color="#10b981" transparent opacity={0.5} />
              </mesh>
            </group>

            {/* Magnetic Field Vector B at M */}
            <group position={[mX, mY, 0]} rotation={[currentDirection === 1 ? -Math.PI / 2 : Math.PI / 2, 0, 0]}> {/* Pointing -Z or +Z */}
              <Cylinder args={[0.03, 0.03, bVisLength, 8]} position={[0, bVisLength / 2, 0]}>
                <meshBasicMaterial color="#10b981" />
              </Cylinder>
              <mesh position={[0, bVisLength, 0]}>
                <coneGeometry args={[0.08, 0.25, 8]} />
                <meshBasicMaterial color="#10b981" />
              </mesh>
              <Html position={[0, bVisLength + 0.3, 0]} center>
                <div className="text-emerald-400 font-bold text-xs drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">B⃗</div>
              </Html>
            </group>

            {/* Traveling contribution dot */}
            <TravelingDot segStart={-visualHalfLength} segEnd={visualHalfLength} mPos={[mX, mY, 0]} speed={0.4 * currentDirection} />
          </group>

          <OrbitControls enablePan={false} minDistance={3} maxDistance={15} />
                    </Suspense>
          </Canvas>
      </div>

      {/* Controls Panel */}
      <div className="w-full bg-card border border-border border-t-0 rounded-b-2xl p-3 sm:p-4 flex flex-col lg:flex-row items-center justify-between gap-4 sm:gap-6">
        
        {/* Group 1: Sliders */}
        <div className="flex flex-col sm:flex-row items-center justify-center gap-4 w-full lg:w-auto flex-1 max-w-md lg:max-w-xl">
          {/* Slider: L */}
          <div className={`flex items-center gap-2 w-full sm:w-32 shrink-0 transition-opacity ${isInfinite ? "opacity-30 pointer-events-none" : "opacity-100"}`}>
            <label className="text-[10px] font-bold text-cyan-400 uppercase w-2">L</label>
            <input type="range" min={0.5} max={6} step={0.1} value={halfLength} onChange={(e) => setHalfLength(parseFloat(e.target.value))} className="w-full h-1.5 sm:h-2 rounded-lg appearance-none cursor-pointer accent-cyan-400 shadow-inner" style={{ background: `linear-gradient(to right, #22d3ee ${percL}%, rgba(30,41,59,0.5) ${percL}%)` }} />
          </div>

          {/* Slider: d */}
          <div className="flex items-center gap-2 w-full sm:w-32 shrink-0">
            <label className="text-[10px] font-bold text-pink-400 uppercase w-2">d</label>
            <input type="range" min={0.5} max={5} step={0.1} value={distance} onChange={(e) => setDistance(parseFloat(e.target.value))} className="w-full h-1.5 sm:h-2 rounded-lg appearance-none cursor-pointer accent-pink-400 shadow-inner" style={{ background: `linear-gradient(to right, #f472b6 ${percD}%, rgba(30,41,59,0.5) ${percD}%)` }} />
          </div>

          {/* Slider: z */}
          <div className="flex items-center gap-2 w-full sm:w-32 shrink-0">
            <label className="text-[10px] font-bold text-purple-400 uppercase w-2">z</label>
            <input type="range" min={-5} max={5} step={0.1} value={heightM} onChange={(e) => setHeightM(parseFloat(e.target.value))} className="w-full h-1.5 sm:h-2 rounded-lg appearance-none cursor-pointer accent-purple-400 shadow-inner" style={{ background: `linear-gradient(to right, #c084fc ${percZ}%, rgba(30,41,59,0.5) ${percZ}%)` }} />
          </div>
        </div>

        {/* Group 2: Buttons */}
        <div className="flex flex-row items-center justify-center gap-3 sm:gap-4 shrink-0">
          {/* Toggle: Sens du courant */}
          <div className="flex items-center bg-slate-800/50 p-1 rounded-xl shrink-0 border border-border/50">
            <button
              onClick={() => setCurrentDirection(1)}
              className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${currentDirection === 1 ? 'bg-cyan-500/20 text-cyan-400 shadow-[0_0_10px_rgba(6,182,212,0.3)]' : 'text-slate-500 hover:text-slate-300'}`}
              title="Courant vers le haut"
            >
              <ArrowUp className="w-4 h-4" />
            </button>
            <button
              onClick={() => setCurrentDirection(-1)}
              className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${currentDirection === -1 ? 'bg-cyan-500/20 text-cyan-400 shadow-[0_0_10px_rgba(6,182,212,0.3)]' : 'text-slate-500 hover:text-slate-300'}`}
              title="Courant vers le bas"
            >
              <ArrowDown className="w-4 h-4" />
            </button>
          </div>

          {/* Toggle: Fil Infini */}
          <button
            onClick={() => setIsInfinite(!isInfinite)}
            className={`flex items-center justify-center w-9 h-9 rounded-xl border transition-all shadow-sm shrink-0 ${
              isInfinite 
                ? "border-amber-400 bg-amber-500/20 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)]" 
                : "border-slate-700/50 bg-slate-800/50 text-slate-400 hover:bg-slate-700 hover:text-white"
            }`}
            title="Cas Infini"
          >
            <InfinityIcon className="w-5 h-5" />
          </button>

          {/* Reset Button */}
          <button 
             onClick={() => {
               setHalfLength(3.0);
               setDistance(2.0);
               setHeightM(0.0);
               setCurrentDirection(1);
               setIsInfinite(false);
             }}
             title="Réinitialiser"
             className="flex items-center justify-center w-9 h-9 bg-slate-800/50 text-slate-400 hover:text-white hover:bg-slate-700 rounded-xl transition-all shadow-inner border border-slate-700/50 shrink-0"
          >
            <RotateCcw className="w-4 h-4" />
          </button>
        </div>
      </div>

        {/* Result display */}
        <div className="w-full flex items-center justify-center text-emerald-500 dark:text-emerald-400 overflow-x-auto py-2 px-1">
          {isInfinite ? (
            <LatexMath 
               math={`\\vec{B}(M) = \\frac{\\mu_0 I}{2\\pi d} \\vec{k} \\approx ${ (currentDirection * 2 / distance).toFixed(3) } \\frac{\\mu_0 I}{4\\pi} \\vec{k}`} 
               block={false} 
               className="text-[10px] sm:text-sm whitespace-nowrap"
            />
          ) : (
            <LatexMath 
               math={`\\vec{B}(M) = \\frac{\\mu_0 I}{4\\pi d} \\left[ \\sin(${ (alpha2 * 180 / Math.PI).toFixed(1) }^\\circ) - \\sin(${ (alpha1 * 180 / Math.PI).toFixed(1) }^\\circ) \\right] \\vec{k} \\approx ${ (currentDirection * (Math.sin(alpha2) - Math.sin(alpha1)) / distance).toFixed(3) } \\frac{\\mu_0 I}{4\\pi} \\vec{k}`} 
               block={false} 
               className="text-[10px] sm:text-sm whitespace-nowrap"
            />
          )}
        </div>
      </div>
  );
}

"use client";

import React, { Suspense, useRef, useState, useMemo, useEffect } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { OrbitControls, Line, Sphere, Cone, Tube, Html } from "@react-three/drei";
import * as THREE from "three";
import LatexMath from "@/components/ui/LatexMath";
import { RotateCcw } from "lucide-react";

// --- Vectors & Arrows Helper ---
interface ArrowProps {
  start: THREE.Vector3;
  dir: THREE.Vector3;
  length: number;
  color: string;
  headSize?: number;
  thickness?: number;
  opacity?: number;
  dashed?: boolean;
}

const Arrow3D: React.FC<ArrowProps> = ({
  start,
  dir,
  length,
  color,
  headSize = 0.4,
  thickness = 2,
  opacity = 1,
  dashed = false,
}) => {
  const normDir = dir.clone().normalize();
  const end = start.clone().add(normDir.clone().multiplyScalar(length));
  
  const linePoints = [start, end];

  return (
    <group>
      <Line
        points={linePoints}
        color={color}
        lineWidth={thickness}
        transparent
        opacity={opacity}
        dashed={dashed}
        dashSize={0.2}
        gapSize={0.1}
      />
      <Cone
        args={[headSize * 0.4, headSize]}
        position={end}
        quaternion={new THREE.Quaternion().setFromUnitVectors(
          new THREE.Vector3(0, 1, 0),
          normDir
        )}
        material={new THREE.MeshBasicMaterial({ color, transparent: true, opacity })}
      />
    </group>
  );
};

const SpireScene = ({ radius, distance, currentDirection, planeMode, circuitShape }: { radius: number, distance: number, currentDirection: number, planeMode: "none" | "sym" | "antisym", circuitShape: "spire" | "bobine" | "solenoide" }) => {
  const [time, setTime] = useState(0);
  const groupRef = useRef<THREE.Group>(null);
  
  useFrame((_, delta) => {
    setTime(t => t + delta * 2);
    if (groupRef.current && groupRef.current.scale.x < 0.84) {
       groupRef.current.scale.lerp(new THREE.Vector3(0.85, 0.85, 0.85), delta * 8);
    }
  });

  // Geometry
  const pM = new THREE.Vector3(distance, -radius, 0); 
  const rDist = Math.sqrt(radius * radius + distance * distance);
  
  // Field calculation
  const sinAlpha = radius / rDist;
  const bMag = (Math.pow(sinAlpha, 3) / radius) * 8; 
  
  const pVec = new THREE.Vector3(0, radius, 0);
  const mVec = new THREE.Vector3(distance, 0, 0);
  const vecPM = new THREE.Vector3().subVectors(mVec, pVec);
  
  const dbDir = new THREE.Vector3(radius, distance, 0).normalize();
  if (currentDirection === -1) dbDir.negate();
  
  const dbMag = bMag * 1.5; 

  const endDb = mVec.clone().add(dbDir.clone().multiplyScalar(dbMag));
  const endB = mVec.clone().add(new THREE.Vector3(currentDirection, 0, 0).multiplyScalar(bMag));

  // Alpha angle
  const thetaStartAlpha = Math.atan2(radius, -distance);
  const thetaLengthAlpha = Math.PI - thetaStartAlpha;
  const midAlpha = thetaStartAlpha + thetaLengthAlpha / 2;
  const alphaLabelPos = new THREE.Vector3(distance + 1.2 * Math.cos(midAlpha), 1.2 * Math.sin(midAlpha), 0);

  // Theta angle
  const angleDb = Math.atan2(dbDir.y, dbDir.x);
  let thetaStartTheta = 0;
  let thetaLengthTheta = angleDb;
  if (angleDb < 0) {
     thetaStartTheta = angleDb;
     thetaLengthTheta = -angleDb;
  }
  const midTheta = thetaStartTheta + thetaLengthTheta / 2;
  const thetaLabelPos = new THREE.Vector3(distance + 1.2 * Math.cos(midTheta), 1.2 * Math.sin(midTheta), 0);

  return (
          <group ref={groupRef} scale={[0.01, 0.01, 0.01]}>
            {/* Grid and Axes */}
            <gridHelper args={[20, 20, "#1e293b", "#0f172a"]} position={[0, -4, 0]} />
            <Arrow3D start={new THREE.Vector3(-8, 0, 0)} dir={new THREE.Vector3(1, 0, 0)} length={16} color="#334155" thickness={1} headSize={0.15} opacity={0.5} />
            
            <Arrow3D start={new THREE.Vector3(-8, 0, 0)} dir={new THREE.Vector3(1, 0, 0)} length={16} color="#334155" thickness={1} headSize={0.15} opacity={0.5} />
            
            {/* The Circuits */}
            {circuitShape === "spire" && (
              <group>
                <mesh rotation={[0, Math.PI / 2, 0]}>
                  <torusGeometry args={[radius, 0.08, 64, 100]} />
                  <meshStandardMaterial color="#fb923c" metalness={0.6} roughness={0.2} emissive="#c2410c" emissiveIntensity={0.5} />
                </mesh>
                {/* Highlight dl segment */}
                <mesh rotation={[0, Math.PI / 2, Math.PI/2 - 0.15]}>
                  <torusGeometry args={[radius, 0.082, 16, 32, 0.3]} />
                  <meshStandardMaterial color="#f472b6" emissive="#be185d" emissiveIntensity={0.8} />
                </mesh>
              </group>
            )}

            {circuitShape === "bobine" && (
              <group>
                {[...Array(5)].map((_, i) => (
                  <mesh key={`b-${i}`} rotation={[0, Math.PI / 2, 0]} position={[(i - 2) * 0.1, 0, 0]}>
                    <torusGeometry args={[radius, 0.06, 32, 64]} />
                    <meshStandardMaterial color="#06b6d4" metalness={0.6} roughness={0.2} emissive="#0891b2" emissiveIntensity={0.5} />
                  </mesh>
                ))}
                {/* Highlight dl segment on middle spire */}
                <mesh rotation={[0, Math.PI / 2, Math.PI/2 - 0.15]}>
                  <torusGeometry args={[radius, 0.065, 16, 32, 0.3]} />
                  <meshStandardMaterial color="#f472b6" emissive="#be185d" emissiveIntensity={0.8} />
                </mesh>
              </group>
            )}

            {circuitShape === "solenoide" && (() => {
              class HelixCurve extends THREE.Curve<THREE.Vector3> {
                constructor() { super(); }
                getPoint(t: number, optionalTarget = new THREE.Vector3()) {
                  const turns = 15;
                  const length = 6;
                  const x = (t - 0.5) * length;
                  const angle = t * Math.PI * 2 * turns;
                  return optionalTarget.set(x, Math.cos(angle) * radius, Math.sin(angle) * radius);
                }
              }
              const helix = new HelixCurve();
              return (
                <group>
                  <mesh>
                    <tubeGeometry args={[helix, 300, 0.04, 8, false]} />
                    <meshStandardMaterial color="#f59e0b" metalness={0.6} roughness={0.2} emissive="#d97706" emissiveIntensity={0.5} />
                  </mesh>
                  {/* Fake highlight for dl */}
                  <mesh rotation={[0, Math.PI / 2, Math.PI/2 - 0.15]} position={[0, 0, 0]}>
                    <torusGeometry args={[radius, 0.06, 16, 32, 0.3]} />
                    <meshStandardMaterial color="#f472b6" emissive="#be185d" emissiveIntensity={0.8} />
                  </mesh>
                </group>
              );
            })()}

            {/* Current Direction representation (moving spheres) */}
            {circuitShape === "solenoide" 
              ? [...Array(30)].map((_, i) => {
                  const group = Math.floor(i / 3);
                  const item = i % 3;
                  const baseT = (group / 10) + (item * 0.012);
                  const t = (baseT + (time * 0.05 * currentDirection)) % 1.0;
                  const normalizedT = t < 0 ? t + 1 : t;
                  const turns = 15;
                  const length = 6;
                  const x = (normalizedT - 0.5) * length;
                  const angle = normalizedT * Math.PI * 2 * turns;
                  const y = Math.cos(angle) * radius;
                  const z = Math.sin(angle) * radius;
                  
                  return (
                     <Sphere key={`curr-sol-${i}`} args={[0.09, 16, 16]} position={[x, y, z]}>
                       <meshBasicMaterial color="#fcd34d" />
                     </Sphere>
                  );
                })
              : (circuitShape === "bobine" ? [-0.2, -0.1, 0, 0.1, 0.2] : [0]).flatMap((xOffset, loopIdx) => 
                  [0, Math.PI/2, Math.PI, 3*Math.PI/2, Math.PI/4, 3*Math.PI/4, 5*Math.PI/4, 7*Math.PI/4].map((angleOffset, i) => {
                    const angle = angleOffset + time * currentDirection;
                    const y = radius * Math.cos(angle);
                    const z = radius * Math.sin(angle);
                    return (
                       <Sphere key={`curr-${loopIdx}-${i}`} args={[0.12, 16, 16]} position={[xOffset, y, z]}>
                         <meshBasicMaterial color="#fcd34d" />
                       </Sphere>
                    );
                  })
                )
            }

            {/* Point M */}
            <Sphere args={[0.15, 16, 16]} position={mVec}>
              <meshBasicMaterial color="#34d399" />
            </Sphere>

            {/* Point O (Center) */}
            <Sphere args={[0.1, 16, 16]} position={[0, 0, 0]}>
              <meshBasicMaterial color="#94a3b8" />
            </Sphere>
            <Html position={[0, -0.4, 0]} center className="pointer-events-none">
              <span className="text-slate-400 font-bold italic text-sm">O</span>
            </Html>

            {/* Unit Vector i */}
            <Arrow3D 
              start={new THREE.Vector3(0, 0, 0)} 
              dir={new THREE.Vector3(1, 0, 0)} 
              length={1.5} 
              color="#e2e8f0" 
              thickness={1.5} 
              headSize={0.15} 
            />
            <Html position={[1.5, 0.3, 0]} center className="pointer-events-none">
              <span className="text-slate-200 font-black italic text-xs drop-shadow-md">i</span>
            </Html>

            {/* Point P (Top of spire) */}
            <Sphere args={[0.1, 16, 16]} position={pVec}>
              <meshBasicMaterial color="#f87171" />
            </Sphere>
            <Html position={[0, radius + 0.4, 0]} center className="pointer-events-none">
              <span className="text-red-400 font-bold italic text-sm drop-shadow-md">P</span>
            </Html>

            {/* Radius R */}
            <Line
              points={[new THREE.Vector3(0, 0, 0), pVec]}
              color="#fb923c"
              lineWidth={1.5}
              dashed
              dashSize={0.2}
              gapSize={0.1}
            />
            <Html position={[0, radius / 2, 0]} center className="pointer-events-none pr-4">
              <span className="text-orange-400 font-bold italic text-sm drop-shadow-md">R</span>
            </Html>

            {/* Vector PM (r) */}
            <Arrow3D 
              start={pVec} 
              dir={vecPM} 
              length={rDist} 
              color="#22d3ee" 
              thickness={1.5}
              headSize={0.2}
              dashed={true}
            />

            {/* Unit vector u at P */}
            <Arrow3D 
              start={pVec} 
              dir={vecPM.clone().normalize()} 
              length={1.0} 
              color="#ef4444" 
              thickness={1.5}
              headSize={0.2}
            />
            <Html position={pVec.clone().add(vecPM.clone().normalize().multiplyScalar(1.2))} center className="pointer-events-none mb-4">
              <span className="text-red-500 font-black italic text-xs drop-shadow-md">u</span>
            </Html>
            
            {/* Angle Alpha */}
            <mesh position={mVec}>
               <circleGeometry args={[0.8, 32, thetaStartAlpha, thetaLengthAlpha]} />
               <meshBasicMaterial color="#a78bfa" transparent opacity={0.25} side={THREE.DoubleSide} depthWrite={false} />
            </mesh>
            <Line
              points={[...Array(33)].map((_, i) => new THREE.Vector3(distance + 0.8 * Math.cos(thetaStartAlpha + (i/32)*thetaLengthAlpha), 0.8 * Math.sin(thetaStartAlpha + (i/32)*thetaLengthAlpha), 0))}
              color="#a78bfa"
              lineWidth={2}
            />
            <Html position={alphaLabelPos} center className="pointer-events-none">
              <span className="text-purple-400 font-black italic text-sm drop-shadow-md">α</span>
            </Html>

            {/* Angle Theta */}
            <mesh position={mVec}>
               <circleGeometry args={[0.9, 32, thetaStartTheta, thetaLengthTheta]} />
               <meshBasicMaterial color="#f472b6" transparent opacity={0.25} side={THREE.DoubleSide} depthWrite={false} />
            </mesh>
            <Line
              points={[...Array(33)].map((_, i) => new THREE.Vector3(distance + 0.9 * Math.cos(thetaStartTheta + (i/32)*thetaLengthTheta), 0.9 * Math.sin(thetaStartTheta + (i/32)*thetaLengthTheta), 0))}
              color="#f472b6"
              lineWidth={2}
            />
            <Html position={thetaLabelPos} center className="pointer-events-none">
              <span className="text-pink-400 font-black italic text-sm drop-shadow-md">θ</span>
            </Html>

            {/* dB vector at M */}
            <Arrow3D 
              start={mVec}
              dir={dbDir}
              length={dbMag}
              color="#fb7185"
              headSize={0.15}
              thickness={1.2}
            />
            <Html position={endDb} center className="pointer-events-none -mt-4">
              <span className="text-rose-400 font-black italic text-xs drop-shadow-md">dB</span>
            </Html>

            {/* Total B vector at M */}
            <Arrow3D 
              start={mVec}
              dir={new THREE.Vector3(currentDirection, 0, 0)}
              length={bMag}
              color="#10b981"
              thickness={1.5}
              headSize={0.2}
            />
            <Html position={endB} center className="pointer-events-none -mt-5">
              <span className="text-emerald-400 font-black italic text-sm drop-shadow-md">B</span>
            </Html>

            {/* dl vector at P */}
            <Arrow3D 
              start={pVec}
              dir={new THREE.Vector3(0, 0, currentDirection)}
              length={1.5}
              color="#f472b6"
              thickness={1.5}
              headSize={0.2}
            />
            <Html position={pVec.clone().add(new THREE.Vector3(0, 0, currentDirection * 1.5))} center className="pointer-events-none -mt-4">
              <span className="text-pink-400 font-black italic text-xs drop-shadow-md">dl</span>
            </Html>
            
            {/* Field line simple visualizer */}
            <Line
              points={[new THREE.Vector3(-8, 0, 0), new THREE.Vector3(8, 0, 0)]}
              color="#10b981"
              lineWidth={0.5}
              transparent
              opacity={0.3}
            />

            {/* Planes */}
            {planeMode === "sym" && (
               <group>
                 <mesh rotation={[0, Math.PI / 2, 0]} position={[0, 0, 0]}>
                   <planeGeometry args={[8, 8]} />
                   <meshBasicMaterial color="#3b82f6" transparent opacity={0.15} side={THREE.DoubleSide} depthWrite={false} />
                 </mesh>
                 <Line
                   points={[new THREE.Vector3(0, -4, -4), new THREE.Vector3(0, 4, -4), new THREE.Vector3(0, 4, 4), new THREE.Vector3(0, -4, 4), new THREE.Vector3(0, -4, -4)]}
                   color="#60a5fa"
                   lineWidth={1}
                   dashed
                   dashSize={0.4}
                   gapSize={0.2}
                   transparent
                   opacity={0.5}
                 />
                 <Html position={[0, 4, 4]} center className="pointer-events-none">
                    <div className="bg-slate-900/90 border border-blue-500/30 px-3 py-1.5 rounded-lg whitespace-nowrap shadow-lg">
                       <span className="text-blue-400 font-bold text-[10px] leading-tight block text-center">Plan Π<br/>(Symétrie)</span>
                    </div>
                 </Html>
               </group>
            )}

            {planeMode === "antisym" && (
               <group>
                 <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]}>
                   <planeGeometry args={[8, 8]} />
                   <meshBasicMaterial color="#10b981" transparent opacity={0.15} side={THREE.DoubleSide} depthWrite={false} />
                 </mesh>
                 <Line
                   points={[new THREE.Vector3(-4, 0, -4), new THREE.Vector3(4, 0, -4), new THREE.Vector3(4, 0, 4), new THREE.Vector3(-4, 0, 4), new THREE.Vector3(-4, 0, -4)]}
                   color="#34d399"
                   lineWidth={1}
                   dashed
                   dashSize={0.4}
                   gapSize={0.2}
                   transparent
                   opacity={0.5}
                 />
                 <Html position={[4, 0, 4]} center className="pointer-events-none">
                    <div className="bg-slate-900/90 border border-emerald-500/30 px-3 py-1.5 rounded-lg whitespace-nowrap shadow-lg">
                       <span className="text-emerald-400 font-bold text-[10px] leading-tight block text-center">Plan Π*<br/>(Antisymétrie)</span>
                    </div>
                 </Html>
               </group>
            )}
          </group>
  );
};

export default function BiotSavartSpire3DCanvas() {
  const [radius, setRadius] = useState(2.0); // Radius R of the loop
  const [distance, setDistance] = useState(3.0); // Distance x of point M on axis
  const [currentDirection, setCurrentDirection] = useState<1 | -1>(1); // Direction of I
  const [planeMode, setPlaneMode] = useState<"none" | "sym" | "antisym">("none");
  const [circuitShape, setCircuitShape] = useState<"spire" | "bobine" | "solenoide">("spire");

  // Angle alpha between X axis and PM
  const rDist = Math.sqrt(radius * radius + distance * distance);
  const sinAlpha = radius / rDist;

  const percR = ((radius - 1) / (4 - 1)) * 100;
  const percX = ((distance - (-5)) / (5 - (-5))) * 100;

  const canvasContainerRef = useRef<HTMLDivElement>(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => setInView(entry.isIntersecting),
      { threshold: 0.05 }
    );
    if (canvasContainerRef.current) observer.observe(canvasContainerRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <div className="w-full max-w-[800px] mx-auto flex flex-col">
      {/* Choix du type de circuit */}
      <div className="flex flex-col sm:flex-row gap-2 mb-3 justify-center w-full">
        <button 
          onClick={() => setCircuitShape("spire")} 
          className={`px-3 py-2 rounded-lg font-bold text-xs transition-all border flex items-center justify-center gap-2 ${
            circuitShape === "spire" 
              ? "bg-emerald-500 text-white border-emerald-400 shadow-[0_0_10px_rgba(16,185,129,0.5)]" 
              : "bg-slate-800/50 text-slate-400 border-slate-700 hover:bg-slate-800"
          }`}
        >
          Spire Circulaire
        </button>
        <button 
          onClick={() => setCircuitShape("bobine")} 
          className={`px-3 py-2 rounded-lg font-bold text-xs transition-all border flex items-center justify-center gap-2 ${
            circuitShape === "bobine" 
              ? "bg-cyan-500 text-white border-cyan-400 shadow-[0_0_10px_rgba(6,182,212,0.5)]" 
              : "bg-slate-800/50 text-slate-400 border-slate-700 hover:bg-slate-800"
          }`}
        >
          Bobine Plate
        </button>
        <button 
          onClick={() => setCircuitShape("solenoide")} 
          className={`px-3 py-2 rounded-lg font-bold text-xs transition-all border flex items-center justify-center gap-2 ${
            circuitShape === "solenoide" 
              ? "bg-amber-500 text-white border-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.5)]" 
              : "bg-slate-800/50 text-slate-400 border-slate-700 hover:bg-slate-800"
          }`}
        >
          Solénoïde
        </button>
      </div>

      <div ref={canvasContainerRef} className="w-full h-[300px] sm:h-[400px] bg-slate-950 rounded-t-2xl overflow-hidden relative border border-slate-800 border-b-0 shadow-inner">
        
        <Canvas frameloop={inView ? "always" : "demand"} camera={{ position: [5, 4, 6], fov: 45 }} dpr={[1, 1.5]}>
            <Suspense fallback={null}>
          <color attach="background" args={["#020617"]} />
          <ambientLight intensity={0.5} />
          <directionalLight position={[10, 10, 10]} intensity={1} />
          
          <OrbitControls 
            enableDamping 
            dampingFactor={0.05} 
            makeDefault 
            minDistance={2} 
            maxDistance={20}
          />
          
          <SpireScene radius={radius} distance={distance} currentDirection={currentDirection} planeMode={planeMode} circuitShape={circuitShape} />
                    </Suspense>
          </Canvas>
      </div>

      {/* Controls Panel */}
      <div className="w-full bg-card border border-border border-t-0 rounded-b-2xl p-3 sm:p-4 flex flex-col gap-3 sm:gap-4">
        
        {/* Row 1: Controls */}
        <div className="w-full flex flex-col lg:flex-row items-center justify-between gap-4">
          
          {/* Group 1: Buttons */}
          <div className="flex items-center justify-center gap-3 sm:gap-4 shrink-0">
            {/* Toggle: Sens du courant */}
            <div className="flex items-center bg-slate-800/50 p-1 rounded-xl shrink-0">
              <button
                onClick={() => setCurrentDirection(-1)}
                className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${
                  currentDirection === -1 
                    ? "bg-cyan-500/20 text-cyan-400 shadow-[0_0_10px_rgba(6,182,212,0.3)]" 
                    : "text-slate-500 hover:text-slate-300"
                }`}
              >
                ↑
              </button>
              <button
                onClick={() => setCurrentDirection(1)}
                className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${
                  currentDirection === 1 
                    ? "bg-cyan-500/20 text-cyan-400 shadow-[0_0_10px_rgba(6,182,212,0.3)]" 
                    : "text-slate-500 hover:text-slate-300"
                }`}
              >
                ↓
              </button>
            </div>

            {/* Toggle: Symetry */}
            <div className="flex items-center gap-2 shrink-0">
              <button
                onClick={() => setPlaneMode(planeMode === "sym" ? "none" : "sym")}
                className={`px-4 h-8 text-[12px] sm:text-sm rounded-lg flex items-center justify-center font-bold transition-all border ${
                  planeMode === "sym" 
                    ? "bg-blue-500 text-white border-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.5)]" 
                    : "bg-blue-500/10 text-blue-400 border-blue-500/30 hover:bg-blue-500/20"
                }`}
              >
                Π
              </button>
              <button
                onClick={() => setPlaneMode(planeMode === "antisym" ? "none" : "antisym")}
                className={`px-4 h-8 text-[12px] sm:text-sm rounded-lg flex items-center justify-center font-bold transition-all border ${
                  planeMode === "antisym" 
                    ? "bg-emerald-500 text-white border-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.5)]" 
                    : "bg-emerald-500/10 text-emerald-400 border-emerald-500/30 hover:bg-emerald-500/20"
                }`}
              >
                Π*
              </button>
            </div>
          </div>

          {/* Group 2: Sliders & Reset */}
          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 w-full lg:w-auto">
            {/* Slider: R */}
            <div className="flex items-center gap-2 w-full sm:w-48 md:w-64 shrink-0">
              <label className="text-[10px] font-bold text-orange-400 uppercase w-2">R</label>
              <input 
                type="range" min={1} max={4} step={0.1} value={radius} 
                onChange={(e) => setRadius(parseFloat(e.target.value))} 
                className="w-full h-2 rounded-full appearance-none cursor-pointer shadow-inner [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:h-4 [&::-webkit-slider-thumb]:bg-orange-400 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:shadow-md" 
                style={{ background: `linear-gradient(to right, #fb923c ${percR}%, #f1f5f9 ${percR}%)` }} 
              />
            </div>

            {/* Slider: x */}
            <div className="flex items-center gap-2 w-full sm:w-48 md:w-64 shrink-0">
              <label className="text-[10px] font-bold text-emerald-400 uppercase w-2">x</label>
              <input 
                type="range" min={-5} max={5} step={0.1} value={distance} 
                onChange={(e) => setDistance(parseFloat(e.target.value))} 
                className="w-full h-2 rounded-full appearance-none cursor-pointer shadow-inner [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:h-4 [&::-webkit-slider-thumb]:bg-emerald-400 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:shadow-md" 
                style={{ background: `linear-gradient(to right, #34d399 ${percX}%, #f1f5f9 ${percX}%)` }} 
              />
            </div>

            {/* Reset */}
            <button 
              onClick={() => { setRadius(2.0); setDistance(3.0); setCurrentDirection(1); setPlaneMode("none"); setCircuitShape("spire"); }}
              className="w-8 h-8 rounded-xl bg-slate-800/50 text-slate-400 hover:text-white hover:bg-slate-700 flex items-center justify-center transition-colors shrink-0 shadow-inner border border-slate-700/50"
              title="Réinitialiser"
            >
              <RotateCcw className="w-4 h-4" />
            </button>
          </div>
        </div> {/* End Row 1 */}

        {/* Row 2: Result display */}
        <div className="w-full flex flex-col md:flex-row items-center justify-center gap-4 text-emerald-500 dark:text-emerald-400 overflow-x-auto py-3 px-4 bg-slate-900/50 rounded-xl border border-slate-800/50 shadow-inner">
          <LatexMath 
             math={`\\vec{B}(M) = \\frac{\\mu_0 I R^2}{2(R^2+x^2)^{3/2}} \\vec{i}`} 
             block={false} 
             className="text-sm sm:text-base whitespace-nowrap font-bold"
          />
          <span className="hidden md:block text-slate-500">ou bien</span>
          <LatexMath 
             math={`\\vec{B}(M) = \\frac{\\mu_0 I}{2 R} \\sin^3(\\alpha) \\vec{i} \\approx ${ (currentDirection * Math.pow(sinAlpha, 3) / radius).toFixed(3) } \\frac{\\mu_0 I}{2} \\vec{i}`} 
             block={false} 
             className="text-[13px] sm:text-[15px] font-bold whitespace-nowrap"
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { Suspense, useState, useMemo, useRef, useEffect } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { OrbitControls, Line, Html, Environment, ContactShadows, Cylinder, Sphere } from "@react-three/drei";
import * as THREE from "three";
import { RotateCcw } from "lucide-react";
import LatexMath from "@/components/ui/LatexMath";

// Helper component for animated contour/field lines
function AmpereContour({ radius, isZero = false }: { radius: number, isZero?: boolean }) {
  const points = useMemo(() => {
    const pts = [];
    for (let i = 0; i <= 64; i++) {
      const angle = (i / 64) * Math.PI * 2;
      pts.push(new THREE.Vector3(radius * Math.cos(angle), 0, radius * Math.sin(angle)));
    }
    return pts;
  }, [radius]);

  const groupRef = useRef<THREE.Group>(null);
  
  useFrame(() => {
    if (groupRef.current && !isZero) {
      groupRef.current.rotation.y += 0.005;
    }
  });

  const color = "#f43f5e"; // rose for contour
  const opacity = 0.8;
  const lineWidth = 3;

  return (
    <group ref={groupRef}>
      <Line points={points} color={color} lineWidth={lineWidth} transparent opacity={opacity} />
      {!isZero && [0, Math.PI, Math.PI/2, 3*Math.PI/2].map((angle, idx) => (
        <group key={idx} position={[radius * Math.cos(angle), 0, radius * Math.sin(angle)]} rotation={[0, angle, 0]}>
          <mesh rotation={[-Math.PI/2, 0, 0]}>
            <coneGeometry args={[0.15, 0.4, 16]} />
            <meshBasicMaterial color={color} transparent opacity={opacity + 0.2} />
          </mesh>
        </group>
      ))}
    </group>
  );
}

function SurfaceCurrentDensity({ radius, height, dirI, color }: { radius: number, height: number, dirI: number, color: string }) {
  const arrows = useMemo(() => {
    const arr = [];
    // more arrows for larger radius
    const numArrows = Math.floor(16 * radius);
    for (let i = 0; i < numArrows; i++) {
      const angle = (i / numArrows) * Math.PI * 2;
      arr.push(new THREE.Vector3(radius * Math.cos(angle), 0, radius * Math.sin(angle)));
    }
    return arr;
  }, [radius]);

  const groupRef = useRef<THREE.Group>(null);
  useFrame(({ clock }) => {
     if (groupRef.current) {
        groupRef.current.position.y = (clock.elapsedTime * 1.5 * dirI) % 1;
     }
  });

  return (
    <group>
      <group ref={groupRef}>
        {[-3, -1, 1, 3].map((yOffset, i) => (
          <group key={i} position={[0, yOffset, 0]}>
            {arrows.map((pos, j) => (
              <group key={j} position={[pos.x, 0, pos.z]} rotation={[dirI > 0 ? 0 : Math.PI, 0, 0]}>
                <mesh rotation={[0, 0, 0]}>
                  <coneGeometry args={[0.05, 0.3, 8]} />
                  <meshBasicMaterial color={color} transparent opacity={0.8} />
                </mesh>
                <mesh position={[0, -0.3, 0]}>
                  <cylinderGeometry args={[0.015, 0.015, 0.6]} />
                  <meshBasicMaterial color={color} transparent opacity={0.6} />
                </mesh>
              </group>
            ))}
          </group>
        ))}
      </group>
    </group>
  );
}

function CoaxialScene({ rho, R1, R2, planeMode }: { rho: number, R1: number, R2: number, planeMode: string }) {
  let bMag = 0;
  let isZero = true;
  let dirB = 1;

  if (rho > R1 && rho < R2) {
    bMag = (R1 * 2) / rho; // B field from inner cylinder
    isZero = false;
    dirB = 1; // + theta
  } else if (rho >= R2) {
    bMag = 0; // Ideal coaxial: sum I_enl = 0
    isZero = true;
  }
  
  const bVectorLength = bMag * 0.6; 
  const bColor = "#34d399"; // emerald-400

  return (
    <group position={[0, 0, 0]}>
      {/* Inner Cylinder R1 (Copper/Orange) */}
      <Cylinder args={[R1, R1, 8, 32]} position={[0, 0, 0]}>
        <meshPhysicalMaterial color="#f97316" metalness={0.6} roughness={0.3} transparent opacity={0.4} side={THREE.DoubleSide} />
      </Cylinder>
      <Line points={(() => {
        const pts = [];
        for(let i=0; i<=32; i++) pts.push(new THREE.Vector3(R1*Math.cos(i*2*Math.PI/32), 4, R1*Math.sin(i*2*Math.PI/32)));
        return pts;
      })()} color="#fdba74" lineWidth={1} transparent opacity={0.6} />
      <Line points={(() => {
        const pts = [];
        for(let i=0; i<=32; i++) pts.push(new THREE.Vector3(R1*Math.cos(i*2*Math.PI/32), -4, R1*Math.sin(i*2*Math.PI/32)));
        return pts;
      })()} color="#fdba74" lineWidth={1} transparent opacity={0.6} />
      <SurfaceCurrentDensity radius={R1} height={8} dirI={1} color="#fcd34d" />
      <Html position={[R1, 3, 0]} center>
        <div className="text-amber-400 font-bold font-serif italic text-sm drop-shadow-md pointer-events-none">j<sub>s1</sub></div>
      </Html>

      {/* Outer Cylinder R2 (Gray/Blue) */}
      <Cylinder args={[R2, R2, 8, 32]} position={[0, 0, 0]}>
        <meshPhysicalMaterial color="#64748b" metalness={0.8} roughness={0.2} transparent opacity={0.15} side={THREE.DoubleSide} />
      </Cylinder>
      <Line points={(() => {
        const pts = [];
        for(let i=0; i<=32; i++) pts.push(new THREE.Vector3(R2*Math.cos(i*2*Math.PI/32), 4, R2*Math.sin(i*2*Math.PI/32)));
        return pts;
      })()} color="#94a3b8" lineWidth={1} transparent opacity={0.4} />
      <Line points={(() => {
        const pts = [];
        for(let i=0; i<=32; i++) pts.push(new THREE.Vector3(R2*Math.cos(i*2*Math.PI/32), -4, R2*Math.sin(i*2*Math.PI/32)));
        return pts;
      })()} color="#94a3b8" lineWidth={1} transparent opacity={0.4} />
      <SurfaceCurrentDensity radius={R2} height={8} dirI={-1} color="#60a5fa" />
      <Html position={[R2, -3, 0]} center>
        <div className="text-blue-400 font-bold font-serif italic text-sm drop-shadow-md pointer-events-none">- j<sub>s2</sub></div>
      </Html>

      {/* Sym Plane (XY plane containing cylinder axis (Y) and M (X)) => Normal is Z */}
      {planeMode === "sym" && (
        <group>
          <mesh position={[0, 0, 0]} rotation={[0, 0, 0]}>
            <planeGeometry args={[12, 8]} />
            <meshPhysicalMaterial color="#3b82f6" transparent opacity={0.15} side={THREE.DoubleSide} metalness={0.9} roughness={0.1} />
          </mesh>
          <Line points={[[-6, 4, 0], [6, 4, 0], [6, -4, 0], [-6, -4, 0], [-6, 4, 0]]} color="#3b82f6" lineWidth={2} dashed dashSize={0.2} gapSize={0.2} />
          <Html position={[0, 3.5, 0]} center zIndexRange={[100,0]}>
            <div className="text-blue-400 font-bold bg-slate-900/80 px-2 py-0.5 rounded text-[10px] border border-blue-500/30 backdrop-blur-md whitespace-nowrap flex flex-col items-center gap-0.5 pointer-events-none">
              <span>Plan Π</span>
              <span className="text-[8px] text-blue-300/80">(Symétrie)</span>
            </div>
          </Html>
        </group>
      )}

      {/* Anti-Sym Plane (XZ plane perpendicular to cylinder (Y) passing through M) => Normal is Y */}
      {planeMode === "antisym" && (
        <group>
          <mesh position={[0, 0, 0]} rotation={[-Math.PI/2, 0, 0]}>
            <planeGeometry args={[12, 12]} />
            <meshPhysicalMaterial color="#10b981" transparent opacity={0.15} side={THREE.DoubleSide} metalness={0.9} roughness={0.1} />
          </mesh>
          <Line points={[[-6, 0, 6], [6, 0, 6], [6, 0, -6], [-6, 0, -6], [-6, 0, 6]]} color="#10b981" lineWidth={2} dashed dashSize={0.2} gapSize={0.2} />
          <Html position={[0, 0, 4.5]} center zIndexRange={[100,0]}>
            <div className="text-emerald-400 font-bold bg-slate-900/80 px-2 py-0.5 rounded text-[10px] border border-emerald-500/30 backdrop-blur-md whitespace-nowrap flex flex-col items-center gap-0.5 pointer-events-none">
              <span>Plan Π*</span>
              <span className="text-[8px] text-emerald-300/80">(Antisymétrie)</span>
            </div>
          </Html>
        </group>
      )}

      {/* Contour d'Ampère */}
      <AmpereContour radius={rho} isZero={isZero} />

      {/* Centre O du contour */}
      <group position={[0, 0, 0]}>
        <Sphere args={[0.08, 16, 16]}>
          <meshBasicMaterial color="#f43f5e" />
        </Sphere>
        <Html position={[0, 0.3, 0]} center zIndexRange={[100,0]}>
          <div className="text-rose-400 font-bold font-serif text-sm drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] pointer-events-none">O</div>
        </Html>
      </group>

      {/* Rayon ρ du contour */}
      <Line points={[[0, 0, 0], [rho, 0, 0]]} color="#f43f5e" lineWidth={2} dashed dashSize={0.2} gapSize={0.1} />
      <Html position={[rho / 2, 0.2, 0]} center zIndexRange={[100,0]}>
        <div className="text-rose-400 font-bold font-serif italic text-sm drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] pointer-events-none">ρ</div>
      </Html>

      {/* Point M */}
      <group position={[rho, 0, 0]}>
        <Sphere args={[0.12, 16, 16]}>
          <meshStandardMaterial color="#f8fafc" emissive="#94a3b8" />
        </Sphere>
        <Html position={[0.1, 0.3, 0]} center zIndexRange={[100,0]}>
          <div className="text-white font-black font-serif text-base drop-shadow-md pointer-events-none">M</div>
        </Html>

        {/* Local Basis */}
        <group>
          <Line points={[[0,0,0], [1.2, 0, 0]]} color="#c084fc" lineWidth={2} />
          <mesh position={[1.2, 0, 0]} rotation={[0, 0, -Math.PI/2]}>
            <coneGeometry args={[0.08, 0.2, 16]} />
            <meshBasicMaterial color="#c084fc" toneMapped={false} />
          </mesh>
          <Html position={[1.5, 0, 0]} center zIndexRange={[100,0]}><div className="text-purple-300 text-[12px] italic font-bold pointer-events-none drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">e<sub>ρ</sub></div></Html>

          <Line points={[[0,0,0], [0, 1.2, 0]]} color="#c084fc" lineWidth={2} />
          <mesh position={[0, 1.2, 0]}>
            <coneGeometry args={[0.08, 0.2, 16]} />
            <meshBasicMaterial color="#c084fc" toneMapped={false} />
          </mesh>
          <Html position={[0, 1.5, 0]} center zIndexRange={[100,0]}><div className="text-purple-300 text-[12px] italic font-bold pointer-events-none drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">e<sub>z</sub></div></Html>

          <Line points={[[0,0,0], [0, 0, -1.2]]} color="#c084fc" lineWidth={2} dashed dashSize={0.1} gapSize={0.05} />
          <mesh position={[0, 0, -1.2]} rotation={[Math.PI/2, 0, 0]}>
            <coneGeometry args={[0.08, 0.2, 16]} />
            <meshBasicMaterial color="#c084fc" toneMapped={false} />
          </mesh>
          <Html position={[0, 0.2, -1.5]} center zIndexRange={[100,0]}><div className="text-purple-300 text-[12px] italic font-bold pointer-events-none drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">e<sub>θ</sub></div></Html>
        </group>

        {/* Magnetic Field Vector B */}
        {!isZero && (
          <group>
            <Line points={[[0,0,0], [0, 0, -dirB * bVectorLength]]} color={bColor} lineWidth={5} />
            <mesh position={[0, 0, -dirB * bVectorLength]} rotation={[dirB > 0 ? -Math.PI/2 : Math.PI/2, 0, 0]}>
              <coneGeometry args={[0.15, 0.4, 16]} />
              <meshBasicMaterial color={bColor} toneMapped={false} />
            </mesh>
            <Html position={[0, 0.3, -dirB * (bVectorLength + 0.3)]} center zIndexRange={[100,0]}>
              <div className="text-emerald-400 font-black italic font-serif text-sm drop-shadow-[0_0_8px_rgba(52,211,153,0.8)] pointer-events-none">B</div>
            </Html>
          </group>
        )}
      </group>
    </group>
  );
}

export default function CoaxialCable3DCanvas() {
  const [rho, setRho] = useState(1.5); // Default in between cylinders
  const [planeMode, setPlaneMode] = useState<"none" | "sym" | "antisym">("none");
  
  const R1 = 0.8;
  const R2 = 1.8;

  const percRho = ((rho - 0.2) / (3.5 - 0.2)) * 100;

  // Determine Zone
  let zoneText = "";
  let bFormula = "";
  if (rho < R1) {
    zoneText = "Zone 1 : À l'intérieur (ρ < R₁)";
    bFormula = "\\vec{B}(M) = \\vec{0}";
  } else if (rho > R1 && rho < R2) {
    zoneText = "Zone 2 : Entre les cylindres (R₁ < ρ < R₂)";
    bFormula = "\\vec{B}(M) = \\frac{\\mu_0 j_{s1} R_1}{\\rho} \\, \\vec{e_\\theta}";
  } else {
    zoneText = "Zone 3 : À l'extérieur (ρ > R₂)";
    // Assuming ideal coaxial cable (I_total = 0)
    bFormula = "\\vec{B}(M) = \\frac{\\mu_0}{\\rho} (j_{s1} R_1 - j_{s2} R_2) \\vec{e_\\theta}";
  }

  const canvasContainerRef = useRef<HTMLDivElement>(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => setInView(entry.isIntersecting),
      { threshold: 0.05 }
    );
    if (canvasContainerRef.current) observer.observe(canvasContainerRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <div className="w-full max-w-[1000px] mx-auto flex flex-col font-sans mb-8">
      
      <div ref={canvasContainerRef} className="w-full h-[300px] sm:h-[400px] bg-slate-950 rounded-t-2xl overflow-hidden relative border border-slate-800 border-b-0 shadow-inner">
        {/* Label Concours */}
        <div className="absolute top-2 left-2 sm:top-4 sm:left-4 z-10 max-w-[calc(100%-1rem)] pointer-events-none">
          <div className="bg-yellow-500/20 border border-yellow-500/50 text-yellow-400 text-[9px] sm:text-xs font-bold px-2 py-1 sm:px-3 rounded-full flex items-center gap-1 sm:gap-2 backdrop-blur-md shadow-lg shadow-yellow-500/10 whitespace-normal text-center sm:text-left leading-tight">
            <span className="w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full bg-yellow-400 animate-pulse shrink-0" />
            Extrait du Concours d'Enseignement 2025
          </div>
        </div>

        <Canvas frameloop={inView ? "always" : "demand"} camera={{ position: [8, 8, 8], fov: 45 }} dpr={[1, 1.5]}>
            <Suspense fallback={null}>
          <color attach="background" args={["#020617"]} />
          <ambientLight intensity={0.5} />
          <spotLight position={[10, 20, 10]} angle={0.4} penumbra={1} intensity={2} color="#e2e8f0" />
          
          <Environment preset="night" />
          <OrbitControls enableDamping dampingFactor={0.05} makeDefault minDistance={3} maxDistance={25} />
          
          <gridHelper args={[24, 24, 0x1e293b, 0x090f1e]} position={[0, -4, 0]} />

          <CoaxialScene rho={rho} R1={R1} R2={R2} planeMode={planeMode} />

          <ContactShadows resolution={512} scale={20} blur={2} opacity={0.5} far={10} color="#000000" position={[0, -3.9, 0]} />
                    </Suspense>
          </Canvas>
      </div>

      {/* Controls Panel */}
      <div className="w-full bg-card border border-border border-t-0 rounded-b-2xl p-3 sm:p-4 flex flex-col gap-3 sm:gap-4 shadow-sm">
        
        {/* Row 1: Controls */}
        <div className="w-full flex flex-col lg:flex-row items-center justify-between gap-4">
          
          {/* Group 1: Buttons */}
          <div className="flex items-center justify-center gap-3 sm:gap-4 shrink-0">
            {/* Toggle: Symetry */}
            <div className="flex items-center gap-2 shrink-0">
              <button
                onClick={() => setPlaneMode(planeMode === "sym" ? "none" : "sym")}
                className={`px-4 h-8 text-[12px] sm:text-sm rounded-lg flex items-center justify-center font-bold transition-all border ${
                  planeMode === "sym" 
                    ? "bg-blue-500 text-white border-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.5)]" 
                    : "bg-blue-500/10 text-blue-400 border-blue-500/30 hover:bg-blue-500/20"
                }`}
              >
                Π
              </button>
              <button
                onClick={() => setPlaneMode(planeMode === "antisym" ? "none" : "antisym")}
                className={`px-4 h-8 text-[12px] sm:text-sm rounded-lg flex items-center justify-center font-bold transition-all border ${
                  planeMode === "antisym" 
                    ? "bg-emerald-500 text-white border-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.5)]" 
                    : "bg-emerald-500/10 text-emerald-400 border-emerald-500/30 hover:bg-emerald-500/20"
                }`}
              >
                Π*
              </button>
            </div>
          </div>

          {/* Group 2: Slider & Reset */}
          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 w-full lg:w-auto">
            {/* Slider: Distance */}
            <div className="flex items-center gap-2 w-full sm:w-64 md:w-80 shrink-0">
              <label className="text-[12px] font-bold text-rose-500 w-2">ρ</label>
              <input 
                type="range" min={0.2} max={3.5} step={0.1} value={rho} 
                onChange={(e) => setRho(parseFloat(e.target.value))} 
                className="w-full h-2 rounded-full appearance-none cursor-pointer shadow-inner [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:h-4 [&::-webkit-slider-thumb]:bg-rose-500 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:shadow-md" 
                style={{ background: `linear-gradient(to right, #f43f5e ${percRho}%, #f1f5f9 ${percRho}%)` }} 
              />
            </div>
            {/* Reset */}
            <button 
              onClick={() => { setRho(1.5); }}
              className="w-8 h-8 rounded-xl bg-slate-800/50 text-slate-400 hover:text-white hover:bg-slate-700 flex items-center justify-center transition-colors shrink-0 shadow-inner border border-slate-700/50"
              title="Réinitialiser"
            >
              <RotateCcw className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Row 2: Result display */}
        <div className="w-full mt-2 bg-slate-900/50 rounded-xl border border-slate-800 p-3 flex flex-col items-center justify-center gap-2">
          <span className="text-slate-400 text-xs font-bold uppercase tracking-wider">{zoneText}</span>
          <div className="text-emerald-400 font-bold flex items-center gap-2 text-sm sm:text-base">
            <LatexMath math={bFormula} block={false} />
          </div>
          {rho >= R2 && (
             <div className="text-[10px] text-yellow-400/80 bg-yellow-950/50 px-3 py-1 rounded-md border border-yellow-500/20 mt-1">
               Idéalement B = 0 si les courants s'annulent (j_{"s1"} R₁ = j_{"s2"} R₂) !
             </div>
          )}
        </div>
      </div>

    </div>
  );
}

