            {/* Badge Info Minimaliste */}
            <div className="absolute top-2.5 left-2.5 z-10 pointer-events-none">
              <div className="bg-slate-900/90 backdrop-blur-md border border-slate-800 px-2.5 py-1 rounded-lg flex items-center gap-2">
                <span className={`w-2 h-2 rounded-full ${currentPreset.isTotal ? "bg-emerald-400" : "bg-amber-400"}`} />
                <span className="text-[10.5px] text-white font-bold">{currentPreset.label}</span>
                <span className="text-[9px] font-bold text-amber-400 bg-amber-500/15 border border-amber-500/30 px-1.5 py-0.2 rounded">
                  δ = {currentPreset.deltaStr}
                </span>
              </div>
            </div>

            <Canvas frameloop={inView ? "always" : "demand"} camera={{ position: [0, 2.2, 4.2], fov: 38 }} className="w-full h-full" dpr={[1, 1.5]}>
            <Suspense fallback={null}>
              <color attach="background" args={["#020617"]} />
              <ambientLight intensity={0.8} />
              <spotLight position={[0, 8, 4]} intensity={1.8} />
              <Environment preset="city" />
              <OrbitControls enableZoom={true} maxPolarAngle={Math.PI / 2.1} />

              <SkinEffectWire3D 
                deltaRatio={currentPreset.deltaRatio} 
                isPlaying={isPlaying} 
                isTotal={currentPreset.isTotal} 
              />

              <ContactShadows resolution={256} scale={8} blur={2} opacity={0.4} far={4} color="#0f172a" position={[0, -1.5, 0]} />
                        </Suspense>
          </Canvas>
          </>
        ) : (
          <CrossSection2DView 
            deltaRatio={currentPreset.deltaRatio} 
            isTotal={currentPreset.isTotal} 
            deltaStr={currentPreset.deltaStr} 
          />
        )}
      </div>

      {/* ── LÉGENDE DU SCHÉMA SOUS LE CANVAS ── */}
      <div className="flex flex-wrap items-center justify-between gap-2 px-1 text-[11px] text-muted-foreground">
        <div className="flex flex-wrap items-center gap-3">
          <span className="flex items-center gap-1 text-amber-400 font-medium">
            <span className="w-2 h-2 rounded-full bg-amber-400" />
            <span>Zone de conduction active (Épaisseur <LatexMath math="\delta" />)</span>
          </span>
          <span className="flex items-center gap-1 text-slate-400 font-medium">
            <span className="w-2 h-2 rounded-full bg-slate-800 border border-slate-600" />
            <span>Cœur inactif (Courant nul)</span>
          </span>
        </div>

        <span className="text-[10.5px] font-mono text-amber-400 font-bold">
          <LatexMath math="\delta = \sqrt{2/(\mu_0 \gamma \omega)}" />
        </span>
      </div>

      {/* ── CONTRÔLES LECTURE ── */}
      {activeView === "3d" && (
        <div className="flex justify-end">
          <button 
            onClick={() => setIsPlaying(!isPlaying)} 
            className="p-1.5 bg-card hover:bg-muted text-foreground rounded-lg border border-border/80 transition-colors text-xs flex items-center gap-1.5"
            title={isPlaying ? "Pause" : "Lecture"}
          >
            {isPlaying ? <Pause className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5" />}
            <span className="text-[11px]">{isPlaying ? "Pause" : "Reprendre le flux"}</span>
          </button>
        </div>
      )}

    </div>
  );
}

"use client";

import React, { Suspense, useState, useMemo, useRef, useEffect } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { OrbitControls, Line, Html, Environment, ContactShadows, Cylinder } from "@react-three/drei";
import * as THREE from "three";
import LatexMath from "@/components/ui/LatexMath";

// A component to draw a dot (current coming out)
function Dot({ position }: { position: [number, number, number] }) {
  return (
    <group position={position}>
      <mesh>
        <circleGeometry args={[0.15, 16]} />
        <meshBasicMaterial color="#f59e0b" side={THREE.DoubleSide} />
      </mesh>
      <mesh position={[0, 0, 0.01]}>
        <circleGeometry args={[0.05, 16]} />
        <meshBasicMaterial color="#78350f" side={THREE.DoubleSide} />
      </mesh>
    </group>
  );
}

// A component to draw a cross (current going in)
function Cross({ position }: { position: [number, number, number] }) {
  return (
    <group position={position}>
      <mesh>
        <circleGeometry args={[0.15, 16]} />
        <meshBasicMaterial color="#f59e0b" side={THREE.DoubleSide} />
      </mesh>
      <Line points={[[-0.1, -0.1, 0.01], [0.1, 0.1, 0.01]]} color="#78350f" lineWidth={3} />
      <Line points={[[-0.1, 0.1, 0.01], [0.1, -0.1, 0.01]]} color="#78350f" lineWidth={3} />
    </group>
  );
}

function AnimatedCurrentRing({ position, radius, color, dirI }: { position: [number, number, number], radius: number, color: string, dirI: number }) {
  const groupRef = React.useRef<THREE.Group>(null);
  
  useFrame(({ clock }) => {
    if (groupRef.current) {
      // Rotate around local Z axis (which is global X after the PI/2 rotation on Y)
      groupRef.current.rotation.z = clock.elapsedTime * 2.0 * dirI; 
    }
  });

  return (
    <group position={position} rotation={[0, Math.PI/2, 0]}>
      <Line points={(() => {
        const pts = [];
        for(let j=0; j<=32; j++) pts.push(new THREE.Vector3(radius*Math.cos(j*2*Math.PI/32), radius*Math.sin(j*2*Math.PI/32), 0));
        return pts;
      })()} color={color} lineWidth={1} transparent opacity={0.3} />
      
      <group ref={groupRef}>
        {[0, Math.PI/2, Math.PI, 3*Math.PI/2].map((angle, idx) => (
          <group key={idx} rotation={[0, 0, angle]}>
            <mesh position={[radius, 0, 0]}>
              <sphereGeometry args={[0.08, 8, 8]} />
              <meshBasicMaterial color={color} />
            </mesh>
            <mesh position={[radius, 0.15 * dirI, 0]} rotation={[0, 0, dirI === 1 ? Math.PI/2 : -Math.PI/2]}>
              <coneGeometry args={[0.06, 0.2, 8]} />
              <meshBasicMaterial color={color} />
            </mesh>
          </group>
        ))}
      </group>
    </group>
  );
}

function AmpereRectangle({ y1, y2, xLen, color, label }: { y1: number, y2: number, xLen: number, color: string, label: string }) {
  // Rectangle ABCD
  // A = (-xLen/2, y1, 0)
  // B = (xLen/2, y1, 0)
  // C = (xLen/2, y2, 0)
  // D = (-xLen/2, y2, 0)
  
  const A = new THREE.Vector3(-xLen/2, y1, 0);
  const B = new THREE.Vector3(xLen/2, y1, 0);
  const C = new THREE.Vector3(xLen/2, y2, 0);
  const D = new THREE.Vector3(-xLen/2, y2, 0);

  const pts = [A, B, C, D, A];

  return (
    <group>
      <Line points={pts} color={color} lineWidth={4} />
      
      {/* Arrows to indicate direction A->B->C->D */}
      <group position={[0, y1, 0]}>
        <mesh rotation={[0, 0, -Math.PI/2]}>
          <coneGeometry args={[0.15, 0.4, 8]} />
          <meshBasicMaterial color={color} />
        </mesh>
      </group>
      <group position={[xLen/2, (y1+y2)/2, 0]}>
        <mesh rotation={[0, 0, y2 > y1 ? 0 : Math.PI]}>
          <coneGeometry args={[0.15, 0.4, 8]} />
          <meshBasicMaterial color={color} />
        </mesh>
      </group>
      <group position={[0, y2, 0]}>
        <mesh rotation={[0, 0, Math.PI/2]}>
          <coneGeometry args={[0.15, 0.4, 8]} />
          <meshBasicMaterial color={color} />
        </mesh>
      </group>
      <group position={[-xLen/2, (y1+y2)/2, 0]}>
        <mesh rotation={[0, 0, y1 > y2 ? 0 : Math.PI]}>
          <coneGeometry args={[0.15, 0.4, 8]} />
          <meshBasicMaterial color={color} />
        </mesh>
      </group>

      {/* Labels */}
      <Html position={[A.x - 0.3, A.y - 0.3, 0]} center>
        <span className="text-white font-bold drop-shadow-md text-xs">A</span>
      </Html>
      <Html position={[B.x + 0.3, B.y - 0.3, 0]} center>
        <span className="text-white font-bold drop-shadow-md text-xs">B</span>
      </Html>
      <Html position={[C.x + 0.3, C.y + 0.3, 0]} center>
        <span className="text-white font-bold drop-shadow-md text-xs">C</span>
      </Html>
      <Html position={[D.x - 0.3, D.y + 0.3, 0]} center>
        <span className="text-white font-bold drop-shadow-md text-xs">D</span>
      </Html>
      
      {/* Contour Label Removed for mobile clarity */}
    </group>
  );
}

function SolenoidScene({ contourMode, planeMode, R, L, dirI }: { contourMode: number, planeMode: string, R: number, L: number, dirI: number }) {
  
  // Solenoid is along X axis, from -L to +L roughly
  // The dots/crosses will be at y = R and y = -R respectively.
  
  const numTurns = 20;
  const turns = useMemo(() => {
    const arr = [];
    for(let i=0; i<=numTurns; i++) {
      const x = -L/2 + (i / numTurns) * L;
      arr.push(x);
    }
    return arr;
  }, [L, numTurns]);

  // Magnetic Field inside is uniform, parallel to X axis
  const B_vectors = [-1.5, 0, 1.5].map(y => {
    return [-L/2 + 1, 0, L/2 - 1].map(x => ({x, y, z: 0}));
  }).flat();

  return (
    <group position={[0, 0, 0]}>
      
      {/* Cylinder Body (Transparent) */}
      <Cylinder args={[R, R, L+1, 32]} rotation={[0, 0, Math.PI/2]} position={[0, 0, 0]}>
        <meshPhysicalMaterial color="#10b981" metalness={0.2} roughness={0.1} transparent opacity={0.1} side={THREE.DoubleSide} />
      </Cylinder>

      {/* Cross section markings (Dots and Crosses) */}
      {turns.map((x, i) => (
        <React.Fragment key={i}>
          {dirI === 1 ? <Dot position={[x, R, 0]} /> : <Cross position={[x, R, 0]} />}
          {dirI === 1 ? <Cross position={[x, -R, 0]} /> : <Dot position={[x, -R, 0]} />}
          {/* Animated Wire circles */}
          <AnimatedCurrentRing position={[x, 0, 0]} radius={R} color="#f59e0b" dirI={dirI} />
        </React.Fragment>
      ))}

      {/* Axis X */}
      <Line points={[[-L/2 - 2, 0, 0], [L/2 + 2, 0, 0]]} color="#94a3b8" lineWidth={1} dashed dashSize={0.2} gapSize={0.2} />
      <Html position={[L/2 + 2.5, 0, 0]} center><span className="text-slate-400 italic">Axe x</span></Html>

      {/* Magnetic Field B (Inside) */}
      {B_vectors.map((pos, idx) => (
        <group key={idx} position={[pos.x, pos.y, pos.z]}>
          <Line points={[[0,0,0], [dirI * 1.5, 0, 0]]} color="#34d399" lineWidth={3} />
          <mesh position={[dirI * 1.5, 0, 0]} rotation={[0, 0, dirI === 1 ? -Math.PI/2 : Math.PI/2]}>
            <coneGeometry args={[0.1, 0.3, 8]} />
            <meshBasicMaterial color="#34d399" />
          </mesh>
          {idx === 4 && (
            <Html position={[0, 0.4, 0]} center>
              <div className="text-emerald-400 font-bold italic font-serif text-sm drop-shadow-md">B<sub>int</sub></div>
            </Html>
          )}
        </group>
      ))}

      {/* Contours based on mode */}
      {contourMode === 1 && (
        <AmpereRectangle y1={-0.8} y2={0.8} xLen={4} color="#ec4899" label="C'₁ (Intérieur)" />
      )}
      {contourMode === 2 && (
        <AmpereRectangle y1={2.5} y2={4.0} xLen={4} color="#3b82f6" label="C'₃ (Extérieur)" />
      )}
      {contourMode === 3 && (
        <AmpereRectangle y1={0.8} y2={3.5} xLen={4} color="#8b5cf6" label="C'₂ (À cheval)" />
      )}

      {/* Anti-Sym Plane (XY plane containing solenoid axis) => Normal is Z */}
      {planeMode === "antisym" && (
        <group>
          <mesh position={[0, 0, 0]} rotation={[0, 0, 0]}>
            <planeGeometry args={[14, 10]} />
            <meshBasicMaterial color="#10b981" transparent opacity={0.15} side={THREE.DoubleSide} />
          </mesh>
          <Line points={[[-7, 5, 0], [7, 5, 0], [7, -5, 0], [-7, -5, 0], [-7, 5, 0]]} color="#10b981" lineWidth={2} dashed dashSize={0.2} gapSize={0.2} />
          <Html position={[0, 4.5, 0]} center zIndexRange={[100,0]}>
            <div className="text-emerald-400 font-bold bg-slate-900/80 px-2 py-0.5 rounded text-[10px] border border-emerald-500/30 backdrop-blur-md flex flex-col items-center pointer-events-none">
              <span>Plan Π*</span>
              <span className="text-[8px] text-emerald-300/80">(Antisymétrie)</span>
            </div>
          </Html>
        </group>
      )}

      {/* Sym Plane (YZ plane perpendicular to solenoid axis) => Normal is X */}
      {planeMode === "sym" && (
        <group>
          <mesh position={[0, 0, 0]} rotation={[0, Math.PI/2, 0]}>
            <planeGeometry args={[10, 10]} />
            <meshBasicMaterial color="#3b82f6" transparent opacity={0.2} side={THREE.DoubleSide} />
          </mesh>
          <Line points={[[0, 5, 5], [0, 5, -5], [0, -5, -5], [0, -5, 5], [0, 5, 5]]} color="#3b82f6" lineWidth={2} dashed dashSize={0.2} gapSize={0.2} />
          <Html position={[0, 4.5, 5]} center zIndexRange={[100,0]}>
            <div className="text-blue-400 font-bold bg-slate-900/80 px-2 py-0.5 rounded text-[10px] border border-blue-500/30 backdrop-blur-md flex flex-col items-center pointer-events-none">
              <span>Plan Π</span>
              <span className="text-[8px] text-blue-300/80">(Symétrie)</span>
            </div>
          </Html>
        </group>
      )}

    </group>
  );
}

export default function Solenoid3DCanvas() {
  const [contourMode, setContourMode] = useState(1); // 1: In, 2: Out, 3: Straddle
  const [planeMode, setPlaneMode] = useState<"none" | "sym" | "antisym">("none");
  const [dirI, setDirI] = useState(1);
  
  const R = 2.0;
  const L = 10.0;

  const canvasContainerRef = useRef<HTMLDivElement>(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => setInView(entry.isIntersecting),
      { threshold: 0.05 }
    );
    if (canvasContainerRef.current) observer.observe(canvasContainerRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <div className="w-full max-w-[1000px] mx-auto flex flex-col font-sans mb-8">
      
      <div ref={canvasContainerRef} className="w-full h-[200px] sm:h-[280px] bg-slate-950 rounded-t-2xl overflow-hidden relative border border-slate-800 border-b-0 shadow-inner">
        <Canvas frameloop={inView ? "always" : "demand"} camera={{ position: [0, 0, 16], fov: 35 }} dpr={[1, 1.5]}>
            <Suspense fallback={null}>
          <color attach="background" args={["#020617"]} />
          <ambientLight intensity={0.5} />
          <spotLight position={[10, 20, 10]} angle={0.4} penumbra={1} intensity={2} color="#e2e8f0" />
          
          <Environment preset="night" />
          {/* Lock rotation slightly to keep the 2D cross section view easily understandable, but allow 3D viewing */}
          <OrbitControls enableDamping dampingFactor={0.05} makeDefault minDistance={5} maxDistance={30} />
          
          <SolenoidScene contourMode={contourMode} planeMode={planeMode} R={R} L={L} dirI={dirI} />

          <ContactShadows resolution={512} scale={30} blur={2} opacity={0.5} far={15} color="#000000" position={[0, -5.9, 0]} />
                    </Suspense>
          </Canvas>
      </div>

      {/* Controls Panel */}
      <div className="w-full bg-card border border-border border-t-0 rounded-b-2xl p-3 sm:p-4 flex flex-col gap-3 sm:gap-4 shadow-sm">
        
        {/* Row 1: Buttons */}
        <div className="w-full flex flex-wrap items-center justify-center gap-3">
          
          {/* Contours */}
          <div className="flex items-center bg-slate-800/50 p-1 rounded-xl shrink-0 border border-slate-700/50">
            <button
              onClick={() => setContourMode(1)}
              className={`px-3 py-1.5 text-xs sm:text-sm font-bold rounded-lg transition-all ${
                contourMode === 1 
                  ? "bg-pink-500/20 text-pink-400 border border-pink-500/30" 
                  : "text-slate-400 hover:text-slate-200"
              }`}
            >
              C'₁ (Intérieur)
            </button>
            <button
              onClick={() => setContourMode(2)}
              className={`px-3 py-1.5 text-xs sm:text-sm font-bold rounded-lg transition-all ${
                contourMode === 2 
                  ? "bg-blue-500/20 text-blue-400 border border-blue-500/30" 
                  : "text-slate-400 hover:text-slate-200"
              }`}
            >
              C'₃ (Extérieur)
            </button>
            <button
              onClick={() => setContourMode(3)}
              className={`px-3 py-1.5 text-xs sm:text-sm font-bold rounded-lg transition-all ${
                contourMode === 3 
                  ? "bg-purple-500/20 text-purple-400 border border-purple-500/30" 
                  : "text-slate-400 hover:text-slate-200"
              }`}
            >
              C'₂ (À cheval)
            </button>
          </div>

          {/* Planes & Direction Toggle */}
          <div className="flex flex-col sm:flex-row items-center gap-3 sm:gap-4 shrink-0">
            {/* Toggle: Current Direction */}
            <button
              onClick={() => setDirI(dirI === 1 ? -1 : 1)}
              className={`px-4 h-8 text-[12px] sm:text-sm rounded-lg flex items-center justify-center font-bold transition-all border ${
                dirI === 1
                  ? "bg-amber-500/10 text-amber-500 border-amber-500/30 hover:bg-amber-500/20"
                  : "bg-red-500/10 text-red-500 border-red-500/30 hover:bg-red-500/20"
              }`}
            >
              Sens I : {dirI === 1 ? "Direct" : "Inverse"}
            </button>

            {/* Toggle: Planes */}
            <div className="flex items-center gap-2">
              <button
                onClick={() => setPlaneMode(planeMode === "sym" ? "none" : "sym")}
                className={`px-4 h-8 text-[12px] sm:text-sm rounded-lg flex items-center justify-center font-bold transition-all border ${
                  planeMode === "sym" 
                    ? "bg-blue-500 text-white border-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.5)]" 
                    : "bg-blue-500/10 text-blue-400 border-blue-500/30 hover:bg-blue-500/20"
                }`}
              >
                Π
              </button>
              <button
                onClick={() => setPlaneMode(planeMode === "antisym" ? "none" : "antisym")}
                className={`px-4 h-8 text-[12px] sm:text-sm rounded-lg flex items-center justify-center font-bold transition-all border ${
                  planeMode === "antisym" 
                    ? "bg-emerald-500 text-white border-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.5)]" 
                    : "bg-emerald-500/10 text-emerald-400 border-emerald-500/30 hover:bg-emerald-500/20"
                }`}
              >
                Π*
              </button>
            </div>
          </div>

        </div>

      </div>

    </div>
  );
}

