          <path d={pathA} fill="none" stroke="#22c55e" strokeWidth="3" className="drop-shadow-[0_0_8px_rgba(34,197,94,0.4)]" />

          {/* Curve B */}
          <path d={pathB} fill="none" stroke="#3b82f6" strokeWidth="3" className="drop-shadow-[0_0_8px_rgba(59,130,246,0.4)]" />

