/* eslint-disable react-hooks/purity */
"use client";

import React, { Suspense, useRef, useState, useEffect, useMemo } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { OrbitControls, Html, Environment, Line } from "@react-three/drei";
import * as THREE from "three";
import { Eye, Navigation } from "lucide-react";
import LatexMath from "@/components/ui/LatexMath";

// Arrow component reused for vectors
function Arrow({ start, dir, length, color, thickness = 0.05, label, labelOffset = [0, 0, 0] }: { start: THREE.Vector3, dir: THREE.Vector3, length: number, color: string, thickness?: number, label?: string, labelOffset?: [number, number, number] }) {
  const normalizedDir = dir.clone().normalize();
  const up = new THREE.Vector3(0, 1, 0);
  let quaternion = new THREE.Quaternion();
  if (Math.abs(normalizedDir.y) === 1) {
    if (normalizedDir.y === -1) {
      quaternion.setFromAxisAngle(new THREE.Vector3(1, 0, 0), Math.PI);
    }
  } else {
    quaternion.setFromUnitVectors(up, normalizedDir);
  }

  return (
    <group position={start}>
      <group quaternion={quaternion}>
        <mesh position={[0, length / 2, 0]}>
          <cylinderGeometry args={[thickness, thickness, length, 12]} />
          <meshBasicMaterial color={color} toneMapped={false} />
        </mesh>
        <mesh position={[0, length + thickness * 1.5, 0]}>
          <coneGeometry args={[thickness * 2.5, thickness * 4, 12]} />
          <meshBasicMaterial color={color} toneMapped={false} />
        </mesh>
      </group>
      {label && (
        <Html position={[normalizedDir.x * (length + 0.1) + labelOffset[0], normalizedDir.y * (length + 0.1) + labelOffset[1], normalizedDir.z * (length + 0.1) + labelOffset[2]]} center>
          <div className="font-bold text-sm drop-shadow-md whitespace-nowrap" style={{ color }}>
            <LatexMath math={label} />
          </div>
        </Html>
      )}
    </group>
  );
}

// B Field Circle (Ampere Contour)
function BFieldCircle({ radius, yPos, color, direction }: { radius: number, yPos: number, color: string, direction: number }) {
  const points = useMemo(() => {
    const pts = [];
    const segments = 64;
    for (let i = 0; i <= segments; i++) {
      const t = (i / segments) * Math.PI * 2;
      pts.push(new THREE.Vector3(Math.cos(t) * radius, yPos, Math.sin(t) * radius));
    }
    return pts;
  }, [radius, yPos]);

  if (radius <= 0.05) return null;

  return (
    <group>
      <Line points={points} color={color} lineWidth={2.5} transparent opacity={0.6} />
      <Arrow start={new THREE.Vector3(radius, yPos, 0)} dir={new THREE.Vector3(0, 0, -direction)} length={0.4} color={color} thickness={0.02} />
      <Arrow start={new THREE.Vector3(-radius, yPos, 0)} dir={new THREE.Vector3(0, 0, direction)} length={0.4} color={color} thickness={0.02} />
      <Arrow start={new THREE.Vector3(0, yPos, radius)} dir={new THREE.Vector3(direction, 0, 0)} length={0.4} color={color} thickness={0.02} />
      <Arrow start={new THREE.Vector3(0, yPos, -radius)} dir={new THREE.Vector3(-direction, 0, 0)} length={0.4} color={color} thickness={0.02} />
    </group>
  );
}

// Animated Current Density (J) - Refined Flow Effect
function AnimatedJField({ radius, direction, magnitude }: { radius: number, direction: number, magnitude: number }) {
  const groupRef = useRef<THREE.Group>(null);

  const sparks = useMemo(() => {
    const items = [];
    const count = Math.max(30, Math.floor(radius * radius * 15)); // Optimal number of sparks
    for (let i = 0; i < count; i++) {
      const r = Math.sqrt(Math.random()) * radius * 0.9;
      const theta = Math.random() * Math.PI * 2;
      const x = r * Math.cos(theta);
      const z = r * Math.sin(theta);
      const y = (Math.random() - 0.5) * 6; // random height between -3 and 3
      const speedOffset = 0.8 + Math.random() * 0.4;
      items.push({ x, y, z, speedOffset });
    }
    return items;
  }, [radius]);

  useFrame((state, delta) => {
    if (groupRef.current) {
      const baseSpeed = 3 * magnitude * direction;
      groupRef.current.children.forEach((child, i) => {
        // Skip the Html child
        if (child.type !== 'Mesh') return;

        const spark = sparks[i];
        if (!spark) return;

        child.position.y += baseSpeed * spark.speedOffset * delta;

        // Wrap around cleanly without mutating shared materials
        if (direction > 0 && child.position.y > 3) {
          child.position.y = -3;
        } else if (direction < 0 && child.position.y < -3) {
          child.position.y = 3;
        }
      });
    }
  });

  return (
    <group ref={groupRef}>
      {sparks.map((spark, i) => (
        <mesh key={i} position={[spark.x, spark.y, spark.z]}>
          <cylinderGeometry args={[0.02, 0.02, 0.6, 6]} />
          <meshBasicMaterial color="#ef4444" transparent opacity={0.8} toneMapped={false} />
        </mesh>
      ))}
      <Html position={[0, direction === 1 ? 3.5 : -3.5, 0]} center>
        <div className="font-bold text-lg text-red-500 drop-shadow-lg bg-black/40 px-2 rounded-full">
          <LatexMath math="\vec{j}" />
        </div>
      </Html>
    </group>
  );
}

// Point M and its vectors
function PointM({ rM, jDirection, jMagnitude, R, showB, showA }: { rM: number, jDirection: number, jMagnitude: number, R: number, showB: boolean, showA: boolean }) {
  const B_mag = rM <= R ? (jMagnitude * rM) / 2 : (jMagnitude * R * R) / (2 * rM);
  const A0 = 2.0;
  let A_mag = 0;
  if (rM <= R) {
    A_mag = A0 - (jMagnitude * rM * rM) / 4;
  } else {
    A_mag = A0 - (jMagnitude * R * R) / 4 - (jMagnitude * R * R / 2) * Math.log(rM / R);
  }

  // Rescaled for better visibility
  const drawLengthB = B_mag * 1.5; 
  const drawLengthA = Math.abs(A_mag) * 1.5;
  const mPos = new THREE.Vector3(rM, 0, 0);

  return (
    <group>
      <mesh position={mPos}>
        <sphereGeometry args={[0.08, 8, 8]} />
        <meshBasicMaterial color="#ffffff" />
      </mesh>

      <Arrow start={mPos} dir={new THREE.Vector3(1,0,0)} length={0.8} color="#a855f7" thickness={0.015} label="\vec{e}_r" labelOffset={[0.1, 0, 0]} />
      <Arrow start={mPos} dir={new THREE.Vector3(0,0,-1)} length={0.8} color="#a855f7" thickness={0.015} label="\vec{e}_\theta" labelOffset={[0, 0, -0.1]} />
      <Arrow start={mPos} dir={new THREE.Vector3(0,1,0)} length={0.8} color="#a855f7" thickness={0.015} label="\vec{e}_z" labelOffset={[0, 0.1, 0]} />

      {showB && B_mag > 0 && (
        <Arrow 
          start={mPos} 
          dir={new THREE.Vector3(0,0, -jDirection)} 
          length={drawLengthB} 
          color="#3b82f6" 
          thickness={0.035} 
          label="\vec{B}(M)"
          labelOffset={[0, -0.2, -jDirection * 0.1]}
        />
      )}

      {showA && A_mag !== 0 && (
        <Arrow 
          start={mPos} 
          dir={new THREE.Vector3(0, Math.sign(A_mag) * jDirection, 0)} 
          length={drawLengthA} 
          color="#22c55e" 
          thickness={0.035} 
          label="\vec{A}(M)"
          labelOffset={[0.2, Math.sign(A_mag) * jDirection * 0.2, 0]}
        />
      )}

      <Line points={[new THREE.Vector3(0,0,0), mPos]} color="#ffffff" transparent opacity={0.3} dashed dashScale={15} dashSize={0.15} gapSize={0.1} />
    </group>
  );
}

// Main visualization component
export default function VectorPotentialExercise3DCanvas() {
  const [showJ, setShowJ] = useState(true);
  const [showB, setShowB] = useState(true);
  const [showA, setShowA] = useState(true);

  const [cylinderRadius, setCylinderRadius] = useState(1.5);
  const [jDirection, setJDirection] = useState<1 | -1>(1);
  const [jMagnitude, setJMagnitude] = useState(1.0);
  const [rM, setRM] = useState(2.0);

  const canvasContainerRef = useRef<HTMLDivElement>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => setInView(entry.isIntersecting), { threshold: 0.05 });
    if (canvasContainerRef.current) observer.observe(canvasContainerRef.current);
    return () => observer.disconnect();
  }, []);

  const topCapPoints = useMemo(() => {
    const pts = [];
    for(let i=0; i<=48; i++) {
      const t = (i/48)*Math.PI*2;
      pts.push(new THREE.Vector3(Math.cos(t)*cylinderRadius, 3, Math.sin(t)*cylinderRadius));
    }
    return pts;
  }, [cylinderRadius]);

  const bottomCapPoints = useMemo(() => {
    const pts = [];
    for(let i=0; i<=48; i++) {
      const t = (i/48)*Math.PI*2;
      pts.push(new THREE.Vector3(Math.cos(t)*cylinderRadius, -3, Math.sin(t)*cylinderRadius));
    }
    return pts;
  }, [cylinderRadius]);

  return (
    <div className="w-full flex flex-col bg-slate-950 rounded-xl overflow-hidden border border-slate-800 shadow-xl" ref={canvasContainerRef}>

      {/* 3D Canvas Area */}
      <div className="w-full h-[300px] sm:h-[350px] relative">
        {inView && (
          <Canvas camera={{ position: [8, 6, 12], fov: 45 }} dpr={[1, 1.5]}>
            <Suspense fallback={null}>
            <color attach="background" args={["#020617"]} />
            <ambientLight intensity={0.5} />
            <directionalLight position={[10, 10, 10]} intensity={1} />

            <OrbitControls enableDamping makeDefault />

            <group position={[0, 0, 0]}>

              {/* Axes X, Y, Z */}
              <Arrow start={new THREE.Vector3(0,0,0)} dir={new THREE.Vector3(1,0,0)} length={5} color="#475569" thickness={0.015} label="\vec{e}_x" />
              <Arrow start={new THREE.Vector3(0,0,0)} dir={new THREE.Vector3(0,1,0)} length={5} color="#475569" thickness={0.015} label="\vec{e}_z" />
              <Arrow start={new THREE.Vector3(0,0,0)} dir={new THREE.Vector3(0,0,1)} length={5} color="#475569" thickness={0.015} label="\vec{e}_y" />

              {/* The Conducting Cylinder */}
              <mesh position={[0, 0, 0]}>
                <cylinderGeometry args={[cylinderRadius, cylinderRadius, 6, 48]} />
                <meshStandardMaterial 
                  color="#64748b" 
                  transparent 
                  opacity={0.15} 
                  roughness={0.4} 
                  side={THREE.DoubleSide}
                />
              </mesh>
              <Line points={topCapPoints} color="#64748b" lineWidth={2} transparent opacity={0.6} />
              <Line points={bottomCapPoints} color="#64748b" lineWidth={2} transparent opacity={0.6} />

              {/* Animated J Field */}
              {showJ && <AnimatedJField radius={cylinderRadius} direction={jDirection} magnitude={jMagnitude} />}

              {/* B Field Line */}
              {showB && (
                <BFieldCircle radius={rM} yPos={0} color="#3b82f6" direction={jDirection} />
              )}

              {/* Point M */}
              <PointM rM={rM} jDirection={jDirection} jMagnitude={jMagnitude} R={cylinderRadius} showB={showB} showA={showA} />

            </group>

            <Environment preset="city" />
                      </Suspense>
          </Canvas>
        )}
      </div>

      {/* Controls Panel */}
      <div className="bg-slate-900 border-t border-slate-800 p-4 sm:p-5">
        <div className="flex flex-col xl:flex-row gap-6 justify-between items-start xl:items-center">

          {/* Toggles Group */}
          <div className="flex flex-col gap-1.5 w-full xl:w-auto shrink-0">
            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider flex items-center gap-1">
              <Eye className="w-3 h-3"/> Affichage & Sens
            </span>
            <div className="flex flex-wrap gap-2">
              <button onClick={() => setShowJ(!showJ)} className={`flex-1 xl:flex-none px-4 py-2 rounded-md flex justify-center items-center gap-1 border transition-all ${showJ ? 'bg-red-500/10 border-red-500/30 text-red-400 shadow-[0_0_10px_rgba(239,68,68,0.1)]' : 'bg-slate-800 border-slate-700 text-slate-500 hover:bg-slate-700'}`}>
                <span className="text-xs font-bold"><LatexMath math="\vec{j}"/></span>
              </button>
              <button onClick={() => setJDirection(d => d === 1 ? -1 : 1)} className="flex-1 xl:flex-none px-4 py-2 rounded-md flex justify-center items-center gap-1 border bg-slate-800 border-slate-700 text-slate-300 hover:bg-slate-700 transition-all shadow-sm">
                <span className="text-xs font-bold flex items-center gap-1">Sens {jDirection === 1 ? "↑" : "↓"}</span>
              </button>
              <button onClick={() => setShowB(!showB)} className={`flex-1 xl:flex-none px-4 py-2 rounded-md flex justify-center items-center gap-1 border transition-all ${showB ? 'bg-blue-500/10 border-blue-500/30 text-blue-400 shadow-[0_0_10px_rgba(59,130,246,0.1)]' : 'bg-slate-800 border-slate-700 text-slate-500 hover:bg-slate-700'}`}>
                <span className="text-xs font-bold"><LatexMath math="\vec{B}"/></span>
              </button>
              <button onClick={() => setShowA(!showA)} className={`flex-1 xl:flex-none px-4 py-2 rounded-md flex justify-center items-center gap-1 border transition-all ${showA ? 'bg-green-500/10 border-green-500/30 text-green-400 shadow-[0_0_10px_rgba(34,197,94,0.1)]' : 'bg-slate-800 border-slate-700 text-slate-500 hover:bg-slate-700'}`}>
                <span className="text-xs font-bold"><LatexMath math="\vec{A}"/></span>
              </button>
            </div>
          </div>

          {/* Sliders Group */}
          <div className="flex-1 w-full grid grid-cols-1 sm:grid-cols-3 gap-6">

            <div className="flex flex-col gap-1.5 w-full">
              <label className="text-[10px] text-slate-400 font-bold uppercase tracking-wider flex justify-between items-center h-5">
                <span>Intensité J</span>
              </label>
              <div className="flex items-center gap-3">
                <input type="range" min="0.5" max="3" step="0.1" value={jMagnitude} onChange={(e) => setJMagnitude(parseFloat(e.target.value))} className="flex-1 accent-red-500 h-1.5" />
                <span className="text-xs text-slate-300 font-mono w-6 text-right shrink-0">{jMagnitude.toFixed(1)}</span>
              </div>
            </div>

            <div className="flex flex-col gap-1.5 w-full">
              <label className="text-[10px] text-slate-400 font-bold uppercase tracking-wider flex justify-between items-center h-5">
                <span>Rayon Cylindre (R)</span>
              </label>
              <div className="flex items-center gap-3">
                <input type="range" min="0.5" max="3" step="0.1" value={cylinderRadius} onChange={(e) => setCylinderRadius(parseFloat(e.target.value))} className="flex-1 accent-slate-400 h-1.5" />
                <span className="text-xs text-slate-300 font-mono w-6 text-right shrink-0">{cylinderRadius.toFixed(1)}</span>
              </div>
            </div>

            <div className="flex flex-col gap-1.5 w-full bg-blue-500/5 p-2 rounded-lg border border-blue-500/10 -m-2">
              <label className="text-[10px] text-blue-300 font-bold uppercase tracking-wider flex justify-between items-center h-4">
                <span>Position Point M (r)</span>
              </label>
              <div className="flex items-center gap-3 mt-1">
                <input type="range" min="0.1" max="5" step="0.1" value={rM} onChange={(e) => setRM(parseFloat(e.target.value))} className="flex-1 accent-blue-400 h-1.5" />
                <span className="text-xs text-blue-300 font-mono w-6 text-right shrink-0">{rM.toFixed(1)}</span>
              </div>
            </div>

          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { Sparkles, Play, Pause, Eye, EyeOff } from "lucide-react";
import LatexMath from "@/components/ui/LatexMath";

export default function ChaslesReferenceFrames3DCanvas() {
  const mountRef = useRef<HTMLDivElement>(null);

  // Interactive Sliders Parameters
  const [thetaDeg, setThetaDeg] = useState<number>(40); // Angle of mobile frame R1 relative to R0
  const [distO1, setDistO1] = useState<number>(3.5); // Distance O -> O1
  const [relMx, setRelMx] = useState<number>(2.8); // Local X of M in R1
  const [relMy, setRelMy] = useState<number>(1.6); // Local Y of M in R1
  const [relMz, setRelMz] = useState<number>(0.8); // Local Z of M in R1
  const [isRotating, setIsRotating] = useState<boolean>(false);
  const [showLegend, setShowLegend] = useState<boolean>(true);

  // Animation Refs
  const animFrameRef = useRef<number | null>(null);
  const isRotatingRef = useRef<boolean>(isRotating);
  const thetaRef = useRef<number>(thetaDeg);
  const angleO1Ref = useRef<number>(20);

  useEffect(() => {
    isRotatingRef.current = isRotating;
  }, [isRotating]);

  useEffect(() => {
    thetaRef.current = thetaDeg;
  }, [thetaDeg]);

  useEffect(() => {
    if (!mountRef.current) return;
    const container = mountRef.current;
    let width = container.clientWidth || 600;
    let height = container.clientHeight || 340;

    // 1. Scene, Camera, Renderer
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x030712);

    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000);
    camera.position.set(8.5, 7.0, 10.5);
    camera.lookAt(1.8, 1.0, 0.5);

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    // Lights
    scene.add(new THREE.AmbientLight(0xffffff, 0.95));
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(8, 12, 10);
    scene.add(dirLight);

    const backLight = new THREE.DirectionalLight(0x38bdf8, 0.5);
    backLight.position.set(-8, 5, -8);
    scene.add(backLight);

    // Dark Floor Grid
    const grid = new THREE.GridHelper(16, 32, 0x334155, 0x1e293b);
    grid.position.y = -0.01;
    scene.add(grid);

    // Helper to create sleek, ultra-thin 3D vectors
    const createThinVector3D = (colorHex: number, shaftRadius: number = 0.018, headRadius: number = 0.055) => {
      const group = new THREE.Group();

      const shaftGeo = new THREE.CylinderGeometry(shaftRadius, shaftRadius, 1, 16);
      shaftGeo.translate(0, 0.5, 0);
      const shaftMat = new THREE.MeshStandardMaterial({
        color: colorHex,
        metalness: 0.3,
        roughness: 0.2,
      });
      const shaft = new THREE.Mesh(shaftGeo, shaftMat);
      group.add(shaft);

      const headGeo = new THREE.ConeGeometry(headRadius, 0.2, 16);
      headGeo.translate(0, 0.1, 0);
      const headMat = new THREE.MeshStandardMaterial({
        color: colorHex,
        metalness: 0.4,
        roughness: 0.2,
      });
      const head = new THREE.Mesh(headGeo, headMat);
      group.add(head);

      return {
        group,
        update: (origin: THREE.Vector3, target: THREE.Vector3) => {
          const dir = new THREE.Vector3().subVectors(target, origin);
          const len = dir.length();
          if (len < 0.05) {
            group.visible = false;
            return;
          }
          group.visible = true;
          group.position.copy(origin);

          const normDir = dir.clone().normalize();
          group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), normDir);

          const headLen = Math.min(0.2, len * 0.22);
          const shaftLen = len - headLen;
          shaft.scale.set(1, Math.max(0.001, shaftLen), 1);
          head.position.set(0, shaftLen, 0);
          const headScale = headLen / 0.2;
          head.scale.set(headScale, headScale, headScale);
        },
      };
    };

    // --- Fixed Reference Frame R0(O, x0, y0, z0) ---
    const r0OriginGeo = new THREE.SphereGeometry(0.12, 32, 32);
    const r0OriginMat = new THREE.MeshStandardMaterial({
      color: 0x3b82f6,
      emissive: 0x1d4ed8,
      emissiveIntensity: 0.8,
    });
    const r0OriginMesh = new THREE.Mesh(r0OriginGeo, r0OriginMat);
    scene.add(r0OriginMesh);

    const vecX0 = createThinVector3D(0x3b82f6, 0.016, 0.05);
    const vecY0 = createThinVector3D(0x3b82f6, 0.016, 0.05);
    const vecZ0 = createThinVector3D(0x3b82f6, 0.016, 0.05);
    scene.add(vecX0.group, vecY0.group, vecZ0.group);

    // --- Mobile Reference Frame R1(O1, x1, y1, z1) ---
    const r1OriginGeo = new THREE.SphereGeometry(0.12, 32, 32);
    const r1OriginMat = new THREE.MeshStandardMaterial({
      color: 0xa855f7,
      emissive: 0x7e22ce,
      emissiveIntensity: 0.8,
    });
    const r1OriginMesh = new THREE.Mesh(r1OriginGeo, r1OriginMat);
    scene.add(r1OriginMesh);

    const vecX1 = createThinVector3D(0xa855f7, 0.016, 0.05);
    const vecY1 = createThinVector3D(0xa855f7, 0.016, 0.05);
    const vecZ1 = createThinVector3D(0xa855f7, 0.016, 0.05);
    scene.add(vecX1.group, vecY1.group, vecZ1.group);

    // --- Point M ---
    const pointMGeo = new THREE.SphereGeometry(0.15, 32, 32);
    const pointMMat = new THREE.MeshStandardMaterial({
      color: 0x38bdf8,
      emissive: 0x0284c7,
      emissiveIntensity: 0.9,
    });
    const pointMMesh = new THREE.Mesh(pointMGeo, pointMMat);
    scene.add(pointMMesh);

    // --- Chasles Relation Main Vectors (Thin & Sleek) ---
    const vecOO1 = createThinVector3D(0xf59e0b, 0.024, 0.07); // OO1 Vector (Amber)
    const vecO1M = createThinVector3D(0x10b981, 0.024, 0.07); // O1M Vector (Emerald)
    const vecOM = createThinVector3D(0x06b6d4, 0.028, 0.08); // OM Vector (Cyan)
    scene.add(vecOO1.group, vecO1M.group, vecOM.group);

    // Dashed helper lines
    const lineMatDashed = new THREE.LineDashedMaterial({
      color: 0x475569,
      dashSize: 0.15,
      gapSize: 0.1,
      transparent: true,
      opacity: 0.5,
    });

    const dashedGeoOO1 = new THREE.BufferGeometry();
    const dashedGeoO1M = new THREE.BufferGeometry();
    const dashedLineOO1 = new THREE.Line(dashedGeoOO1, lineMatDashed);
    const dashedLineO1M = new THREE.Line(dashedGeoO1M, lineMatDashed);
    scene.add(dashedLineOO1, dashedLineO1M);

    // Orbit Controls
    let isDragging = false;
    let prevMouse = { x: 0, y: 0 };
    let cameraAngleX = 0.5;
    let cameraAngleY = 0.4;
    const cameraRadius = 14;

    const updateCameraPosition = () => {
      camera.position.x = 1.8 + cameraRadius * Math.sin(cameraAngleX) * Math.cos(cameraAngleY);
      camera.position.y = 1.0 + cameraRadius * Math.sin(cameraAngleY);
      camera.position.z = cameraRadius * Math.cos(cameraAngleX) * Math.cos(cameraAngleY);
      camera.lookAt(1.8, 1.0, 0);
    };
    updateCameraPosition();

    const onPointerDown = (e: PointerEvent) => {
      isDragging = true;
      prevMouse = { x: e.clientX, y: e.clientY };
    };

    const onPointerMove = (e: PointerEvent) => {
      if (!isDragging) return;
      const dx = e.clientX - prevMouse.x;
      const dy = e.clientY - prevMouse.y;
      cameraAngleX -= dx * 0.008;
      cameraAngleY += dy * 0.008;
      cameraAngleY = Math.max(-Math.PI / 2.5, Math.min(Math.PI / 2.5, cameraAngleY));
      prevMouse = { x: e.clientX, y: e.clientY };
      updateCameraPosition();
    };

    const onPointerUp = () => {
      isDragging = false;
    };

    const handleResize = () => {
      if (!container) return;
      width = container.clientWidth || 600;
      height = container.clientHeight || 340;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    };

    const domElement = renderer.domElement;
    domElement.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("pointercancel", onPointerUp);
    window.addEventListener("resize", handleResize);

    // Convert 3D vector to 2D screen coords for minimal labels
    const toScreenPosition = (v3: THREE.Vector3) => {
      const clone = v3.clone();
      clone.project(camera);
      const x = (clone.x * 0.5 + 0.5) * width;
      const y = (-clone.y * 0.5 + 0.5) * height;
      const visible = clone.z < 1.0;
      return { x, y, visible };
    };

    // Render & Animation Loop
    let lastTime = performance.now();

    const animate = (time: number) => {
      const delta = (time - lastTime) / 1000;
      lastTime = time;

      if (isRotatingRef.current) {
        thetaRef.current = (thetaRef.current + delta * 40) % 360;
        angleO1Ref.current = (angleO1Ref.current + delta * 12) % 360;
      }

      const thetaRad = (thetaRef.current * Math.PI) / 180;
      const angleO1Rad = (angleO1Ref.current * Math.PI) / 180;

      // 1. Origin Positions
      const O = new THREE.Vector3(0, 0, 0);
      const O1 = new THREE.Vector3(
        distO1 * Math.cos(angleO1Rad),
        0.4,
        -distO1 * Math.sin(angleO1Rad)
      );

      // Fixed R0 Axes
      const r0AxisLen = 2.4;
      const pX0 = new THREE.Vector3(r0AxisLen, 0, 0);
      const pY0 = new THREE.Vector3(0, r0AxisLen, 0);
      const pZ0 = new THREE.Vector3(0, 0, r0AxisLen);
      vecX0.update(O, pX0);
      vecY0.update(O, pY0);
      vecZ0.update(O, pZ0);

      // 2. Mobile R1 Axes
      const uX1 = new THREE.Vector3(Math.cos(thetaRad), 0, -Math.sin(thetaRad));
      const uY1 = new THREE.Vector3(0, 1, 0);
      const uZ1 = new THREE.Vector3(Math.sin(thetaRad), 0, Math.cos(thetaRad));

      const r1AxisLen = 2.2;
      const pX1 = O1.clone().add(uX1.clone().multiplyScalar(r1AxisLen));
      const pY1 = O1.clone().add(uY1.clone().multiplyScalar(r1AxisLen));
      const pZ1 = O1.clone().add(uZ1.clone().multiplyScalar(r1AxisLen));

      r1OriginMesh.position.copy(O1);
      vecX1.update(O1, pX1);
      vecY1.update(O1, pY1);
      vecZ1.update(O1, pZ1);

      // 3. Point M Position
      const vecO1M_local = new THREE.Vector3()
        .addScaledVector(uX1, relMx)
        .addScaledVector(uY1, relMy)
        .addScaledVector(uZ1, relMz);

      const M = O1.clone().add(vecO1M_local);
      pointMMesh.position.copy(M);

      // 4. Chasles Relation 3D Vectors
      vecOO1.update(O, O1);
      vecO1M.update(O1, M);
      vecOM.update(O, M);

      // Dashed lines
      dashedGeoOO1.setFromPoints([O, O1]);
      dashedLineOO1.computeLineDistances();
      dashedGeoO1M.setFromPoints([O1, M]);
      dashedLineO1M.computeLineDistances();

      // --- Minimal Screen Projections (Clean, no dark boxes, only key labels) ---
      const spO = toScreenPosition(O.clone().add(new THREE.Vector3(-0.25, -0.2, 0)));
      const spX0 = toScreenPosition(pX0.clone().add(new THREE.Vector3(0.2, 0, 0)));
      const spY0 = toScreenPosition(pY0.clone().add(new THREE.Vector3(0, 0.2, 0)));

      const spO1 = toScreenPosition(O1.clone().add(new THREE.Vector3(-0.25, -0.2, 0)));
      const spX1 = toScreenPosition(pX1.clone().add(new THREE.Vector3(0.2, 0, 0)));
      const spY1 = toScreenPosition(pY1.clone().add(new THREE.Vector3(0, 0.2, 0)));

      const spM = toScreenPosition(M.clone().add(new THREE.Vector3(0.25, 0.2, 0)));

      const updateLabel = (id: string, sp: {x: number, y: number, visible: boolean}) => {
        const el = document.getElementById(`chasles-lbl-${id}`);
        if (!el) return;
        if (sp.visible) {
          el.style.display = 'block';
          el.style.transform = `translate(-50%, -50%) translate(${sp.x}px, ${sp.y}px)`;
        } else {
          el.style.display = 'none';
        }
      };

      updateLabel("O", spO);
      updateLabel("x0", spX0);
      updateLabel("y0", spY0);
      updateLabel("O1", spO1);
      updateLabel("x1", spX1);
      updateLabel("y1", spY1);
      updateLabel("M", spM);

      renderer.render(scene, camera);
      if (isInViewRef.current) animFrameRef.current = requestAnimationFrame(animate);
    };

    const isInViewRef = { current: false };
    const intersectionObserver = new IntersectionObserver(
      ([entry]) => {
        isInViewRef.current = entry.isIntersecting;
        if (isInViewRef.current) animFrameRef.current = requestAnimationFrame(animate);
      },
      { threshold: 0.05 }
    );
    intersectionObserver.observe(container);

    return () => {
      if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
      intersectionObserver.disconnect();
      domElement.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
      window.removeEventListener("pointercancel", onPointerUp);
      window.removeEventListener("resize", handleResize);
      if (container.contains(domElement)) container.removeChild(domElement);
    };
  }, [distO1, relMx, relMy, relMz]);

  return (
    <div className="p-2 sm:p-4 rounded-2xl sm:rounded-3xl bg-slate-950 border border-slate-800 text-white shadow-xl max-w-full overflow-hidden">
      {/* Title Header */}
      <div className="flex flex-wrap items-center justify-between gap-2 mb-3">
        <div className="flex items-center gap-2">
          <Sparkles className="w-4 h-4 text-amber-400 flex-shrink-0" />
          <h3 className="text-xs sm:text-sm font-bold text-amber-400">
            Simulateur 3D : Repères <LatexMath math="\mathcal{R}_0" />, <LatexMath math="\mathcal{R}_1" /> & Chasles <LatexMath math="\vec{OM} = \vec{OO}_1 + \vec{O_1 M}" />
          </h3>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowLegend(!showLegend)}
            className="flex items-center gap-1 px-2.5 py-1 rounded-lg text-[11px] font-mono bg-slate-900 border border-slate-700 text-slate-300 hover:border-slate-500"
          >
            {showLegend ? <EyeOff className="w-3 h-3 text-slate-400" /> : <Eye className="w-3 h-3 text-slate-400" />}
            <span className="hidden sm:inline">{showLegend ? "Masquer Légende" : "Afficher Légende"}</span>
          </button>

          <button
            onClick={() => setIsRotating(!isRotating)}
            className={`flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-bold transition-all border ${
              isRotating
                ? "bg-amber-500/20 text-amber-300 border-amber-500/50 animate-pulse"
                : "bg-slate-900 text-slate-200 border-slate-700 hover:border-slate-500"
            }`}
          >
            {isRotating ? <Pause className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5" />}
            <span>{isRotating ? "Pause Ω" : "Animer Ω"}</span>
          </button>
        </div>
      </div>

      {/* 3D WebGL Canvas */}
      <div 
        className="relative rounded-xl overflow-hidden border border-slate-800 bg-slate-950"
        style={{ touchAction: 'none' }}
      >
        <div ref={mountRef} className="w-full h-[280px] sm:h-[360px] cursor-grab active:cursor-grabbing" />

        {/* Minimal Clean 3D Labels updated directly via DOM for smooth performance */}
        <div className="absolute inset-0 pointer-events-none z-10 overflow-hidden">
          <div id="chasles-lbl-O" className="absolute font-mono text-[10px] sm:text-[11px] drop-shadow-[0_1px_3px_rgba(0,0,0,0.9)] select-none text-blue-400 font-bold top-0 left-0" style={{ display: 'none' }}>O (R0)</div>
          <div id="chasles-lbl-x0" className="absolute font-mono text-[10px] sm:text-[11px] drop-shadow-[0_1px_3px_rgba(0,0,0,0.9)] select-none text-blue-300 top-0 left-0" style={{ display: 'none' }}>x0</div>
          <div id="chasles-lbl-y0" className="absolute font-mono text-[10px] sm:text-[11px] drop-shadow-[0_1px_3px_rgba(0,0,0,0.9)] select-none text-blue-300 top-0 left-0" style={{ display: 'none' }}>y0</div>
          
          <div id="chasles-lbl-O1" className="absolute font-mono text-[10px] sm:text-[11px] drop-shadow-[0_1px_3px_rgba(0,0,0,0.9)] select-none text-purple-400 font-bold top-0 left-0" style={{ display: 'none' }}>O1 (R1)</div>
          <div id="chasles-lbl-x1" className="absolute font-mono text-[10px] sm:text-[11px] drop-shadow-[0_1px_3px_rgba(0,0,0,0.9)] select-none text-purple-300 top-0 left-0" style={{ display: 'none' }}>x1</div>
          <div id="chasles-lbl-y1" className="absolute font-mono text-[10px] sm:text-[11px] drop-shadow-[0_1px_3px_rgba(0,0,0,0.9)] select-none text-purple-300 top-0 left-0" style={{ display: 'none' }}>y1</div>
          
          <div id="chasles-lbl-M" className="absolute font-mono text-[10px] sm:text-[11px] drop-shadow-[0_1px_3px_rgba(0,0,0,0.9)] select-none text-sky-300 font-black text-xs top-0 left-0" style={{ display: 'none' }}>M</div>
        </div>

        {/* Collapsible Clean Overlay Legend */}
        {showLegend && (
          <div className="absolute top-2 left-2 bg-slate-900/90 backdrop-blur-md p-2 rounded-lg border border-slate-800 text-[10px] font-mono space-y-1 shadow-lg pointer-events-none max-w-[220px] sm:max-w-none">
            <div className="flex items-center gap-2 text-blue-400 font-bold">
              <span className="w-2 h-2 rounded-full bg-blue-400 inline-block" />
              <span>R0 Fixe (O, x0, y0, z0)</span>
            </div>

            <div className="flex items-center gap-2 text-purple-400 font-bold">
              <span className="w-2 h-2 rounded-full bg-purple-400 inline-block" />
              <span>R1 Mobile (O1, x1, y1, z1)</span>
            </div>

            <div className="pt-1 border-t border-slate-800 space-y-0.5 text-[9.5px]">
              <div className="flex items-center gap-1.5 text-amber-400">
                <span className="w-2 h-0.5 bg-amber-400 inline-block" />
                <span>Vecteur OO1 (Ambre)</span>
              </div>

              <div className="flex items-center gap-1.5 text-emerald-400">
                <span className="w-2 h-0.5 bg-emerald-400 inline-block" />
                <span>Vecteur O1M (Émeraude)</span>
              </div>

              <div className="flex items-center gap-1.5 text-cyan-400 font-bold">
                <span className="w-2 h-0.5 bg-cyan-400 inline-block" />
                <span>Vecteur OM = OO1 + O1M (Cyan)</span>
              </div>
            </div>
          </div>
        )}

        {/* Chasles Formula Card */}
        <div className="absolute bottom-2 right-2 bg-slate-900/90 backdrop-blur-md px-2.5 py-1 rounded-lg border border-slate-800 text-[10px] sm:text-[11px] font-mono text-slate-200 shadow-md">
          <span className="text-amber-400 font-bold">Chasles : </span>
          <LatexMath math="\vec{OM} = \vec{OO}_1 + \vec{O_1 M}" />
        </div>
      </div>

      {/* Compact Sliders Panel (Responsive on Mobile) */}
      <div className="mt-2.5 grid grid-cols-1 sm:grid-cols-3 gap-2 p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-[11px] font-mono">
        {/* Slider 1: Orientation Theta */}
        <div className="flex flex-col gap-0.5">
          <div className="flex justify-between text-slate-300">
            <span>Orientation <LatexMath math="\theta" />:</span>
            <span className="text-purple-400 font-bold">{thetaDeg}°</span>
          </div>
          <input
            type="range"
            min="0"
            max="360"
            value={thetaDeg}
            onChange={(e) => {
              const val = parseFloat(e.target.value);
              setThetaDeg(val);
              thetaRef.current = val;
            }}
            className="w-full h-1.5 accent-purple-500 cursor-pointer rounded-lg bg-slate-800"
          />
        </div>

        {/* Slider 2: Position OO1 */}
        <div className="flex flex-col gap-0.5">
          <div className="flex justify-between text-slate-300">
            <span>Distance <LatexMath math="OO_1" />:</span>
            <span className="text-amber-400 font-bold">{distO1.toFixed(1)} m</span>
          </div>
          <input
            type="range"
            min="1.0"
            max="5.0"
            step="0.1"
            value={distO1}
            onChange={(e) => setDistO1(parseFloat(e.target.value))}
            className="w-full h-1.5 accent-amber-500 cursor-pointer rounded-lg bg-slate-800"
          />
        </div>

        {/* Slider 3: Position O1M */}
        <div className="flex flex-col gap-0.5">
          <div className="flex justify-between text-slate-300">
            <span>Composante X de <LatexMath math="\vec{O_1 M}" />:</span>
            <span className="text-emerald-400 font-bold">{relMx.toFixed(1)} m</span>
          </div>
          <input
            type="range"
            min="0.5"
            max="4.0"
            step="0.1"
            value={relMx}
            onChange={(e) => setRelMx(parseFloat(e.target.value))}
            className="w-full h-1.5 accent-emerald-500 cursor-pointer rounded-lg bg-slate-800"
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { Activity, Eye, Sliders, RotateCw, ArrowUpRight, Radio } from "lucide-react";
import LatexMath from "@/components/ui/LatexMath";

type OperatorType = "gradient" | "divergence" | "rotationnel";

export default function DifferentialOperators3DSimulator() {
  const mountRef = useRef<HTMLDivElement | null>(null);
  const [operatorType, setOperatorType] = useState<OperatorType>("gradient");

  // Control parameters
  const [amplitude, setAmplitude] = useState(2.5); // Gradient height / Divergence strength / Vortex speed
  const [spread, setSpread] = useState(2.0); // Surface spread / Field radius

  const sceneRef = useRef<THREE.Scene | null>(null);
  const meshGroupRef = useRef<THREE.Group | null>(null);

  useEffect(() => {
    const container = mountRef.current;
    if (!container) return;

    container.innerHTML = "";
    const width = container.clientWidth || 320;
    const height = container.clientHeight || 280;

    let webglSupported = false;
    try {
      const testCanvas = document.createElement("canvas");
      webglSupported = !!(window.WebGLRenderingContext && (testCanvas.getContext("webgl") || testCanvas.getContext("experimental-webgl")));
    } catch (e) {
      webglSupported = false;
    }

    if (!webglSupported) return;

    // 1. Scene, Camera, Renderer
    const scene = new THREE.Scene();
    sceneRef.current = scene;
    scene.background = new THREE.Color(0x090d16);

    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000);
    camera.position.set(5.5, 4.5, 6.5);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    // 2. Lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 1.2);
    scene.add(ambientLight);

    const dirLight1 = new THREE.DirectionalLight(0x38bdf8, 1.5);
    dirLight1.position.set(8, 12, 8);
    scene.add(dirLight1);

    const dirLight2 = new THREE.DirectionalLight(0xf43f5e, 0.8);
    dirLight2.position.set(-8, -8, -8);
    scene.add(dirLight2);

    // 3. Grid Helper
    const gridHelper = new THREE.GridHelper(8, 8, 0x3b82f6, 0x1e293b);
    gridHelper.position.y = 0;
    scene.add(gridHelper);

    // 4. Main 3D Object Group
    const meshGroup = new THREE.Group();
    scene.add(meshGroup);
    meshGroupRef.current = meshGroup;

    // 5. Mouse Drag Controls
    let isDragging = false;
    let prevX = 0;
    let prevY = 0;
    let camSpherical = new THREE.Spherical().setFromVector3(camera.position);

    const onStart = (clientX: number, clientY: number) => {
      isDragging = true;
      prevX = clientX;
      prevY = clientY;
    };

    const onMove = (clientX: number, clientY: number) => {
      if (!isDragging) return;
      const deltaX = clientX - prevX;
      const deltaY = clientY - prevY;

      camSpherical.theta -= deltaX * 0.008;
      camSpherical.phi = Math.max(0.1, Math.min(Math.PI - 0.1, camSpherical.phi - deltaY * 0.008));

      camera.position.setFromSpherical(camSpherical);
      camera.lookAt(0, 0, 0);

      prevX = clientX;
      prevY = clientY;
    };

    const onEnd = () => {
      isDragging = false;
    };

    const domElem = renderer.domElement;
    domElem.addEventListener("mousedown", (e) => onStart(e.clientX, e.clientY));
    window.addEventListener("mousemove", (e) => onMove(e.clientX, e.clientY));
    window.addEventListener("mouseup", onEnd);

    domElem.addEventListener("touchstart", (e) => {
      if (e.touches.length === 1) onStart(e.touches[0].clientX, e.touches[0].clientY);
    }, { passive: true });
    window.addEventListener("touchmove", (e) => {
      if (e.touches.length === 1) onMove(e.touches[0].clientX, e.touches[0].clientY);
    }, { passive: true });
    window.addEventListener("touchend", onEnd);

    const handleResize = () => {
      if (!container) return;
      const newW = container.clientWidth;
      const newH = container.clientHeight;
      camera.aspect = newW / newH;
      camera.updateProjectionMatrix();
      renderer.setSize(newW, newH);
    };
    window.addEventListener("resize", handleResize);

    let animId: number;
    let isInView = false;
    let time = 0;
    const animate = () => {
      if (!isInView) return;
      animId = requestAnimationFrame(animate);
      time += 0.02;

      // Rotate particles or vortex in Rotationnel mode
      if (meshGroupRef.current && meshGroupRef.current.userData.rotGroup) {
        meshGroupRef.current.userData.rotGroup.rotation.y = time * (amplitude * 0.4);
      }

      renderer.render(scene, camera);
    };

    const intersectionObserver = new IntersectionObserver(
      ([entry]) => {
        isInView = entry.isIntersecting;
        if (isInView) animate();
      },
      { threshold: 0.05 }
    );
    intersectionObserver.observe(container);

    return () => {
      cancelAnimationFrame(animId);
      intersectionObserver.disconnect();
      window.removeEventListener("resize", handleResize);
      if (container) container.innerHTML = "";
      renderer.dispose();
    };
  }, [amplitude]);

  // Dynamically build 3D geometry based on operatorType, amplitude, spread
  useEffect(() => {
    if (!meshGroupRef.current) return;
    const group = meshGroupRef.current;
    
    // Clear previous mesh objects
    while (group.children.length > 0) {
      const child = group.children[0];
      group.remove(child);
    }
    group.userData = {};

    if (operatorType === "gradient") {
      // --- 1. 3D GRADIENT (Parametric Surface f(x,z) = Amp * exp(-(x^2+z^2)/Spread)) ---
      const gridSegments = 40;
      const size = 5.0;
      const planeGeo = new THREE.PlaneGeometry(size, size, gridSegments, gridSegments);
      planeGeo.rotateX(-Math.PI / 2); // Put on XZ plane

      const posAttr = planeGeo.attributes.position;
      const colors: number[] = [];

      for (let i = 0; i < posAttr.count; i++) {
        const x = posAttr.getX(i);
        const z = posAttr.getZ(i);
        const r2 = x * x + z * z;
        const y = amplitude * Math.exp(-r2 / Math.max(0.5, spread));
        posAttr.setY(i, y);

        // Color gradient from Deep Navy (base) to Bright Cyan (peak)
        const t = y / Math.max(0.1, amplitude);
        const c = new THREE.Color().setHSL(0.55 - t * 0.15, 0.9, 0.3 + t * 0.4);
        colors.push(c.r, c.g, c.b);
      }

      planeGeo.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
      planeGeo.computeVertexNormals();

      const surfMat = new THREE.MeshStandardMaterial({
        vertexColors: true,
        side: THREE.DoubleSide,
        wireframe: false,
        roughness: 0.3,
        metalness: 0.1,
      });
      const surfMesh = new THREE.Mesh(planeGeo, surfMat);
      group.add(surfMesh);

      // Wireframe overlay for 3D depth
      const wireMat = new THREE.MeshBasicMaterial({ color: 0x38bdf8, wireframe: true, transparent: true, opacity: 0.15 });
      const wireMesh = new THREE.Mesh(planeGeo, wireMat);
      group.add(wireMesh);

      // Gradient Vectors pointing UP the steepest slope
      const samplePts = [
        new THREE.Vector3(1.2, 0, 0),
        new THREE.Vector3(-1.2, 0, 0),
        new THREE.Vector3(0, 0, 1.2),
        new THREE.Vector3(0, 0, -1.2),
        new THREE.Vector3(0.9, 0, 0.9),
      ];

      samplePts.forEach((pt) => {
        const r2 = pt.x * pt.x + pt.z * pt.z;
        const y = amplitude * Math.exp(-r2 / Math.max(0.5, spread));
        pt.y = y;

        // Grad f = df/dx i + df/dz k = -2x/S * y i - 2z/S * y k + dy/dt j (up slope)
        const dfdx = (-2 * pt.x / Math.max(0.5, spread)) * y;
        const dfdz = (-2 * pt.z / Math.max(0.5, spread)) * y;
        const gradVec = new THREE.Vector3(-dfdx, 1.5, -dfdz).normalize();

        const gradArrow = new THREE.ArrowHelper(gradVec, pt, 1.0, 0x38bdf8, 0.22, 0.07);
        group.add(gradArrow);
      });

      // Peak Master Gradient Arrow
      const peakPos = new THREE.Vector3(0, amplitude, 0);
      const peakArrow = new THREE.ArrowHelper(new THREE.Vector3(0, 1, 0), peakPos, 1.4, 0x38bdf8, 0.28, 0.09);
      group.add(peakArrow);

    } else if (operatorType === "divergence") {
      // --- 2. 3D DIVERGENCE (Point Source / Translucent Sphere & 3D Radial Arrows) ---
      const rSph = Math.max(1.0, spread * 0.9);
      const sphGeo = new THREE.SphereGeometry(rSph, 32, 24);
      const sphMat = new THREE.MeshStandardMaterial({
        color: amplitude >= 0 ? 0x10b981 : 0xf43f5e,
        transparent: true,
        opacity: 0.15,
        side: THREE.DoubleSide,
        wireframe: true,
      });
      const sphMesh = new THREE.Mesh(sphGeo, sphMat);
      group.add(sphMesh);

      // Central Source Sphere
      const centerGeo = new THREE.SphereGeometry(0.15, 16, 16);
      const centerMat = new THREE.MeshBasicMaterial({ color: amplitude >= 0 ? 0x34d399 : 0xf43f5e });
      const centerMesh = new THREE.Mesh(centerGeo, centerMat);
      group.add(centerMesh);

      // 3D Radial Arrows (Source if amp > 0, Sink if amp < 0)
      const numArrows = 18;
      const isSource = amplitude >= 0;
      const arrowColor = isSource ? 0x34d399 : 0xf43f5e;
      const arrowLen = Math.abs(amplitude) * 0.45;

      for (let i = 0; i < numArrows; i++) {
        // Distribute uniformly on sphere surface
        const phiAngle = Math.acos(-1 + (2 * i) / numArrows);
        const thetaAngle = Math.sqrt(numArrows * Math.PI) * phiAngle;

        const dir = new THREE.Vector3(
          Math.cos(thetaAngle) * Math.sin(phiAngle),
          Math.sin(thetaAngle) * Math.sin(phiAngle),
          Math.cos(phiAngle)
        ).normalize();

        const startPt = isSource ? new THREE.Vector3(0, 0, 0) : dir.clone().multiplyScalar(rSph);
        const arrowDir = isSource ? dir : dir.clone().negate();

        const arrow = new THREE.ArrowHelper(arrowDir, startPt, arrowLen, arrowColor, 0.2, 0.07);
        group.add(arrow);
      }

    } else if (operatorType === "rotationnel") {
      // --- 3. 3D ROTATIONNEL (Swirling Vortex Rings & Central Axis Vector rot A) ---
      const rotGroup = new THREE.Group();
      group.add(rotGroup);
      group.userData.rotGroup = rotGroup;

      const numRings = 5;
      for (let rIdx = 1; rIdx <= numRings; rIdx++) {
        const radius = rIdx * (spread * 0.35);
        const ringGeo = new THREE.RingGeometry(radius - 0.02, radius + 0.02, 32);
        ringGeo.rotateX(Math.PI / 2);

        const ringMat = new THREE.MeshBasicMaterial({
          color: 0xfbbf24,
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.6 - rIdx * 0.08,
        });
        const ringMesh = new THREE.Mesh(ringGeo, ringMat);
        ringMesh.position.y = (rIdx - 3) * 0.4;
        rotGroup.add(ringMesh);

        // Swirling tangent arrows around each ring
        const numTangents = 4;
        for (let tIdx = 0; tIdx < numTangents; tIdx++) {
          const a = (tIdx * 2 * Math.PI) / numTangents;
          const pos = new THREE.Vector3(radius * Math.cos(a), (rIdx - 3) * 0.4, radius * Math.sin(a));
          const tangent = new THREE.Vector3(-Math.sin(a), 0, Math.cos(a)).normalize();

          const arrow = new THREE.ArrowHelper(tangent, pos, 0.6, 0xfbbf24, 0.18, 0.06);
          rotGroup.add(arrow);
        }
      }

      // Central Rotation Axis Vector rot A (Rose Red Vertically Upward)
      const rotAxisLen = Math.max(1.0, amplitude * 0.9);
      const rotAxisArrow = new THREE.ArrowHelper(
        new THREE.Vector3(0, 1, 0),
        new THREE.Vector3(0, -1.2, 0),
        rotAxisLen + 1.2,
        0xf43f5e,
        0.3,
        0.1
      );
      group.add(rotAxisArrow);
    }
  }, [operatorType, amplitude, spread]);

  return (
    <div className="bg-slate-950/95 border border-slate-800 rounded-2xl sm:rounded-3xl p-3 sm:p-5 shadow-2xl my-6 w-full max-w-full overflow-hidden">
      
      {/* Header & Tabs */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 mb-3 pb-3 border-b border-slate-800">
        <div className="flex items-center gap-2">
          <Activity className="w-5 h-5 text-cyan-400 shrink-0" />
          <div>
            <h3 className="text-xs sm:text-sm font-extrabold text-white leading-tight">
              Simulateur 3D Interactif • Opérateurs Différentiels (Grad, Div, Rot)
            </h3>
            <p className="text-[11px] text-slate-400 font-medium">
              Faites glisser en 3D et modifiez l'intensité pour observer le comportement physique en direct
            </p>
          </div>
        </div>

        {/* Operator Selection Buttons */}
        <div className="grid grid-cols-3 gap-1 bg-slate-900/90 p-1 rounded-xl border border-slate-800 shrink-0">
          <button
            onClick={() => setOperatorType("gradient")}
            className={`px-2.5 py-1.5 rounded-lg text-[10px] sm:text-xs font-bold transition-all flex items-center justify-center gap-1 ${
              operatorType === "gradient" ? "bg-cyan-500 text-slate-950 shadow-sm" : "text-slate-400 hover:text-white"
            }`}
          >
            <ArrowUpRight className="w-3.5 h-3.5" />
            <span>Gradient (∇f)</span>
          </button>
          <button
            onClick={() => setOperatorType("divergence")}
            className={`px-2.5 py-1.5 rounded-lg text-[10px] sm:text-xs font-bold transition-all flex items-center justify-center gap-1 ${
              operatorType === "divergence" ? "bg-emerald-500 text-slate-950 shadow-sm" : "text-slate-400 hover:text-white"
            }`}
          >
            <Radio className="w-3.5 h-3.5" />
            <span>Div (∇·A)</span>
          </button>
          <button
            onClick={() => setOperatorType("rotationnel")}
            className={`px-2.5 py-1.5 rounded-lg text-[10px] sm:text-xs font-bold transition-all flex items-center justify-center gap-1 ${
              operatorType === "rotationnel" ? "bg-amber-500 text-slate-950 shadow-sm" : "text-slate-400 hover:text-white"
            }`}
          >
            <RotateCw className="w-3.5 h-3.5" />
            <span>Rot (∇∧A)</span>
          </button>
        </div>
      </div>

      {/* 3D WebGL Canvas Container */}
      <div className="relative w-full h-[250px] sm:h-[300px] rounded-xl sm:rounded-2xl overflow-hidden shadow-inner border border-slate-800 cursor-grab active:cursor-grabbing">
        <div ref={mountRef} className="w-full h-full" />

        {/* View Indicator */}
        <div className="absolute top-2.5 right-2.5 bg-slate-950/90 backdrop-blur-md px-2 py-1 rounded-lg border border-white/10 text-[10px] text-slate-300 flex items-center gap-1">
          <Eye className="w-3.5 h-3.5 text-cyan-400" />
          <span>Faites glisser en 3D</span>
        </div>

        {/* Current Operator Physics Explanation Overlay */}
        <div className="absolute top-2.5 left-2.5 bg-slate-950/90 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/10 text-xs font-mono">
          {operatorType === "gradient" && (
            <div className="text-cyan-400 font-bold flex items-center gap-1.5">
              <span className="w-2 h-2 rounded-full bg-cyan-400 inline-block" />
              <span>Gradient ∇f: Pente maximale (Hauteur = {amplitude.toFixed(1)})</span>
            </div>
          )}
          {operatorType === "divergence" && (
            <div className={`font-bold flex items-center gap-1.5 ${amplitude >= 0 ? "text-emerald-400" : "text-rose-400"}`}>
              <span className={`w-2 h-2 rounded-full inline-block ${amplitude >= 0 ? "bg-emerald-400" : "bg-rose-400"}`} />
              <span>{amplitude >= 0 ? "div A > 0 (Source de flux)" : "div A < 0 (Puits de flux)"}</span>
            </div>
          )}
          {operatorType === "rotationnel" && (
            <div className="text-amber-400 font-bold flex items-center gap-1.5">
              <span className="w-2 h-2 rounded-full bg-amber-400 inline-block" />
              <span>rot A ≠ 0: Tourbillonnement (Vitesse ω = {amplitude.toFixed(1)})</span>
            </div>
          )}
        </div>

        {/* Bottom Formula Legend */}
        <div className="absolute bottom-2.5 left-2.5 right-2.5 bg-slate-950/90 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/10 text-[11px] font-mono text-slate-200 flex items-center justify-between overflow-x-auto">
          {operatorType === "gradient" && (
            <>
              <LatexMath math="\vec{\mathrm{grad}}(f) = \frac{\partial f}{\partial x}\vec{i} + \frac{\partial f}{\partial y}\vec{j} + \frac{\partial f}{\partial z}\vec{k}" />
              <span className="text-cyan-400 font-bold ml-2">Perpendiculaire aux équipotentielles</span>
            </>
          )}
          {operatorType === "divergence" && (
            <>
              <LatexMath math="\mathrm{div}(\vec{A}) = \vec{\nabla} \cdot \vec{A} = \frac{\partial A_x}{\partial x} + \frac{\partial A_y}{\partial y} + \frac{\partial A_z}{\partial z}" />
              <span className="text-emerald-400 font-bold ml-2">Flux surfacique sortant net</span>
            </>
          )}
          {operatorType === "rotationnel" && (
            <>
              <LatexMath math="\vec{\mathrm{rot}}(\vec{A}) = \vec{\nabla} \wedge \vec{A} = \text{Axe de Rotation 3D}" />
              <span className="text-amber-400 font-bold ml-2">Règle de la main droite</span>
            </>
          )}
        </div>
      </div>

      {/* Sliders Controls Panel */}
      <div className="mt-3 grid grid-cols-1 sm:grid-cols-2 gap-3 bg-slate-900/60 p-3 rounded-xl border border-slate-800">
        <div>
          <label className="text-xs font-bold text-slate-200 flex items-center justify-between mb-1.5">
            <span>
              {operatorType === "gradient" ? "Hauteur du relief (A):" : operatorType === "divergence" ? "Débit du Flux (q):" : "Vitesse du Tourbillon (ω):"}
            </span>
            <span className="text-cyan-400 font-extrabold">{amplitude.toFixed(1)}</span>
          </label>
          <input
            type="range"
            min={operatorType === "divergence" ? "-4.0" : "0.5"}
            max="5.0"
            step="0.2"
            value={amplitude}
            onChange={(e) => setAmplitude(Number(e.target.value))}
            className="w-full accent-cyan-400 cursor-pointer h-1.5 bg-slate-800 rounded-lg"
          />
        </div>

        <div>
          <label className="text-xs font-bold text-slate-200 flex items-center justify-between mb-1.5">
            <span>
              {operatorType === "gradient" ? "Étalement / Pente (S):" : operatorType === "divergence" ? "Rayon de la sphère (R):" : "Rayon du Vortex (r):"}
            </span>
            <span className="text-purple-400 font-extrabold">{spread.toFixed(1)}</span>
          </label>
          <input
            type="range"
            min="1.0"
            max="4.0"
            step="0.2"
            value={spread}
            onChange={(e) => setSpread(Number(e.target.value))}
            className="w-full accent-purple-400 cursor-pointer h-1.5 bg-slate-800 rounded-lg"
          />
        </div>
      </div>

    </div>
  );
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import { Sparkles, Play, Pause, RotateCcw, BookOpen, ChevronDown, ChevronUp, CheckCircle2, HelpCircle, FileText } from "lucide-react";
import LatexMath from "@/components/ui/LatexMath";

export default function ExerciseCircleRolling3DCanvas() {
  // Collapsible state for the ENTIRE Exercice 1 block (Closed by default)
  const [isExerciseOpen, setIsExerciseOpen] = useState<boolean>(false);

  // Mode: "FIXED" (Tableau) vs "ANIMATED" (Mouvement 2D)
  const [mode, setMode] = useState<"FIXED" | "ANIMATED">("FIXED");
  const [omega, setOmega] = useState<number>(1.2); // Vitesse angulaire w (rad/s)
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  
  // Solution drawer hidden by default so students solve it first!
  const [showSolution, setShowSolution] = useState<boolean>(false);

  // Animation time state for 2D animated mode (60fps smooth loop)
  const [animTime, setAnimTime] = useState<number>(0);
  const animFrameRef = useRef<number | null>(null);
  const timeRef = useRef<number>(0);
  const isPlayingRef = useRef<boolean>(isPlaying);
  const omegaRef = useRef<number>(omega);
  const trail2DRef = useRef<{ x: number; y: number }[]>([]);

  useEffect(() => {
    isPlayingRef.current = isPlaying;
  }, [isPlaying]);

  useEffect(() => {
    omegaRef.current = omega;
  }, [omega]);

  // Ultra-Smooth 60 FPS Animation loop — pauses when out of viewport
  const containerRef = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    if (!isExerciseOpen || mode !== "ANIMATED") return;
    let running = false;
    let animRef: number | null = null;

    const startLoop = () => {
      if (running) return;
      running = true;
      let last = performance.now();
      const loop = (now: number) => {
        const delta = Math.min((now - last) / 1000, 0.04);
        last = now;
        if (isPlayingRef.current) {
          timeRef.current += delta * omegaRef.current * 0.75;
          setAnimTime(timeRef.current);
        }
        if (running) animRef = requestAnimationFrame(loop);
      };
      animRef = requestAnimationFrame(loop);
    };

    const stopLoop = () => {
      running = false;
      if (animRef !== null) cancelAnimationFrame(animRef);
    };

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) startLoop();
        else stopLoop();
      },
      { threshold: 0.05 }
    );
    if (containerRef.current) observer.observe(containerRef.current);

    return () => {
      stopLoop();
      observer.disconnect();
    };
  }, [isExerciseOpen, mode]);

  const handleReset = () => {
    timeRef.current = 0;
    setAnimTime(0);
    trail2DRef.current = [];
  };

  // --- 2D Animated Geometry Scale (Compact 460x270 ViewBox) ---
  const R_anim = 42;
  const thetaAnim = animTime;
  const O_anim = { x: 180, y: 135 };

  const O1_anim = {
    x: O_anim.x + R_anim * Math.cos(thetaAnim),
    y: O_anim.y - R_anim * Math.sin(thetaAnim),
  };

  const A_anim = {
    x: O_anim.x + 2 * R_anim * Math.cos(thetaAnim),
    y: O_anim.y - 2 * R_anim * Math.sin(thetaAnim),
  };

  const ux1_anim = { x: Math.cos(thetaAnim), y: -Math.sin(thetaAnim) };
  const uy1_anim = { x: -Math.sin(thetaAnim), y: -Math.cos(thetaAnim) };

  const relAngleAnim = animTime;
  const M_anim = {
    x: O1_anim.x + R_anim * (ux1_anim.x * Math.cos(relAngleAnim) + uy1_anim.x * Math.sin(relAngleAnim)),
    y: O1_anim.y + R_anim * (ux1_anim.y * Math.cos(relAngleAnim) + uy1_anim.y * Math.sin(relAngleAnim)),
  };

  useEffect(() => {
    if (isExerciseOpen && mode === "ANIMATED" && isPlaying) {
      const trail = trail2DRef.current;
      if (trail.length === 0) {
        trail.push({ x: M_anim.x, y: M_anim.y });
      } else {
        const lastPt = trail[trail.length - 1];
        const dist = Math.hypot(lastPt.x - M_anim.x, lastPt.y - M_anim.y);
        
        if (dist > 12.0) {
          trail2DRef.current = [{ x: M_anim.x, y: M_anim.y }];
        } else if (dist > 1.8) {
          trail.push({ x: M_anim.x, y: M_anim.y });
          if (trail.length > 450) trail.shift();
        }
      }
    }
  }, [M_anim.x, M_anim.y, mode, isPlaying, isExerciseOpen]);

  useEffect(() => {
    if (mode === "ANIMATED") {
      trail2DRef.current = [];
    }
  }, [mode]);

  // --- Fixed 2D Diagram Constants ---
  const R_fixed = 72;
  const thetaFixed = (30 * Math.PI) / 180;
  const O_fixed = { x: 75, y: 175 };

  const O1_fixed = {
    x: O_fixed.x + R_fixed * Math.cos(thetaFixed),
    y: O_fixed.y - R_fixed * Math.sin(thetaFixed),
  };
  const A_fixed = {
    x: O_fixed.x + 2 * R_fixed * Math.cos(thetaFixed),
    y: O_fixed.y - 2 * R_fixed * Math.sin(thetaFixed),
  };
  const ux1_fixed = { x: Math.cos(thetaFixed), y: -Math.sin(thetaFixed) };
  const uy1_fixed = { x: -Math.sin(thetaFixed), y: -Math.cos(thetaFixed) };

  const M_fixed = {
    x: O1_fixed.x + R_fixed * (ux1_fixed.x * Math.cos(thetaFixed) + uy1_fixed.x * Math.sin(thetaFixed)),
    y: O1_fixed.y + R_fixed * (ux1_fixed.y * Math.cos(thetaFixed) + uy1_fixed.y * Math.sin(thetaFixed)),
  };

  return (
    <div ref={containerRef} className="rounded-2xl sm:rounded-3xl bg-slate-950 border border-slate-800 text-white shadow-2xl max-w-full overflow-hidden mb-5">
      
      {/* 1. EXERCICE 1 ACCORDION HEADER BAR (ALWAYS VISIBLE & COLLAPSIBLE BY DEFAULT) */}
      <button
        onClick={() => setIsExerciseOpen(!isExerciseOpen)}
        className="w-full flex items-center justify-between p-4 sm:p-5 bg-slate-900/90 hover:bg-slate-900 transition-all text-left border-b border-slate-800/80"
      >
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-xl bg-amber-500/10 border border-amber-500/30 text-amber-400">
            <FileText className="w-5 h-5" />
          </div>
          <div>
            <h3 className="text-base sm:text-xl font-black text-amber-400 flex items-center gap-2">
              <span>Exercice 1</span>
            </h3>
            <p className="text-[11px] sm:text-xs text-slate-400">
              Composition de Mouvement : Cercle Tournant & Point Matériel <LatexMath math="M" />
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <span className="hidden sm:inline-block text-[11px] font-mono font-bold px-2.5 py-1 rounded-lg bg-indigo-500/10 border border-indigo-500/30 text-indigo-300">
            {isExerciseOpen ? "Exercice Ouvert" : "Cliquez pour Ouvrir"}
          </span>
          <div className="p-1.5 rounded-xl bg-slate-800 text-amber-400 border border-slate-700">
            {isExerciseOpen ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
          </div>
        </div>
      </button>

      {/* 2. EXERCICE 1 EXPANDABLE BODY */}
      {isExerciseOpen && (
        <div className="p-3 sm:p-5 space-y-4 animate-in fade-in duration-200">
          
          {/* ÉNONCÉ DE L'EXERCICE (DU TABLEAU) */}
          <div className="p-3.5 sm:p-4 rounded-xl bg-slate-900/90 border border-slate-800/90 space-y-2 text-xs sm:text-sm font-sans shadow-md">
            <div className="flex items-center gap-2 text-amber-400 font-bold border-b border-slate-800 pb-1.5 text-xs sm:text-sm">
              <HelpCircle className="w-3.5 h-3.5 text-amber-400 flex-shrink-0" />
              <span>Énoncé de l'Exercice (Du Tableau) :</span>
            </div>
            
            <p className="text-slate-300 leading-normal font-mono text-[11px] sm:text-xs">
              Dans le plan <LatexMath math="(Oxy)" />, un cercle de diamètre <LatexMath math="OA = 2R" /> tourne à vitesse angulaire constante <LatexMath math="\omega" /> autour de <LatexMath math="O" />.<br />
              On lie à son centre mobile <LatexMath math="O_1" />, 2 axes <LatexMath math="(O_1 x_1)" /> et <LatexMath math="(O_1 y_1)" />. Un point <LatexMath math="M" />, initialement en <LatexMath math="A" />, parcourt le cercle à la même vitesse angulaire <LatexMath math="\omega" />.
            </p>

            <div className="pt-1 grid grid-cols-1 sm:grid-cols-2 gap-1.5 text-slate-200 font-mono text-[10.5px] sm:text-xs">
              <div className="p-1.5 rounded-lg bg-slate-950/80 border border-slate-800 flex items-center gap-1.5">
                <span className="w-4 h-4 rounded bg-cyan-500/20 text-cyan-400 font-bold flex items-center justify-center text-[9px] flex-shrink-0">1</span>
                <span>Exprimer <LatexMath math="\vec{OO}_1" /> et <LatexMath math="\vec{O_1 M}" /> dans <LatexMath math="(\vec{i}_1, \vec{j}_1)" />.</span>
              </div>

              <div className="p-1.5 rounded-lg bg-slate-950/80 border border-slate-800 flex items-center gap-1.5">
                <span className="w-4 h-4 rounded bg-emerald-500/20 text-emerald-400 font-bold flex items-center justify-center text-[9px] flex-shrink-0">2</span>
                <span>Déterminer <LatexMath math="\vec{V}_r(M)" /> et <LatexMath math="\vec{V}_e(M)" />.</span>
              </div>

              <div className="p-1.5 rounded-lg bg-slate-950/80 border border-slate-800 flex items-center gap-1.5">
                <span className="w-4 h-4 rounded bg-rose-500/20 text-rose-400 font-bold flex items-center justify-center text-[9px] flex-shrink-0">3</span>
                <span>Calculer l'accélération de Coriolis <LatexMath math="\vec{\gamma}_c(M)" />.</span>
              </div>

              <div className="p-1.5 rounded-lg bg-slate-950/80 border border-slate-800 flex items-center gap-1.5">
                <span className="w-4 h-4 rounded bg-purple-500/20 text-purple-400 font-bold flex items-center justify-center text-[9px] flex-shrink-0">4</span>
                <span>Déterminer la trajectoire (Cardioïde).</span>
              </div>
            </div>
          </div>

          {/* MODE SELECTOR BAR */}
          <div className="flex flex-wrap items-center justify-between gap-2 p-1.5 rounded-xl bg-slate-900 border border-slate-800">
            <span className="text-xs font-bold text-slate-300 flex items-center gap-1.5 px-1.5">
              <Sparkles className="w-3.5 h-3.5 text-amber-400" />
              <span>Schéma & Animation :</span>
            </span>

            {/* Mode Switcher Tabs */}
            <div className="flex items-center gap-1 bg-slate-950 p-1 rounded-lg border border-slate-800">
              <button
                onClick={() => {
                  setMode("FIXED");
                  setIsPlaying(false);
                }}
                className={`px-2.5 py-1 rounded-md text-[11px] font-bold transition-all ${
                  mode === "FIXED"
                    ? "bg-amber-500 text-slate-950 shadow-sm"
                    : "text-slate-400 hover:text-white"
                }`}
              >
                2D Schéma Fixe (Tableau)
              </button>

              <button
                onClick={() => {
                  setMode("ANIMATED");
                  setIsPlaying(true);
                  trail2DRef.current = [];
                }}
                className={`px-2.5 py-1 rounded-md text-[11px] font-bold transition-all ${
                  mode === "ANIMATED"
                    ? "bg-purple-600 text-white shadow-sm"
                    : "text-slate-400 hover:text-white"
                }`}
              >
                2D Mouvement Animé
              </button>
            </div>
          </div>

          {/* 2D SVG CANVAS CONTAINER */}
          <div className="relative rounded-xl overflow-hidden border border-slate-800 bg-slate-950 flex items-center justify-center p-1 shadow-inner">
            <svg
              viewBox={mode === "FIXED" ? "0 0 440 260" : "0 0 460 270"}
              className="w-full max-w-xl h-auto drop-shadow-md"
            >
              <defs>
                <pattern id="blueprintGrid" width="18" height="18" patternUnits="userSpaceOnUse">
                  <path d="M 18 0 L 0 0 0 18" fill="none" stroke="#1e293b" strokeWidth="0.5" />
                </pattern>

                <filter id="glowBlue" x="-20%" y="-20%" width="140%" height="140%">
                  <feGaussianBlur stdDeviation="2" result="blur" />
                  <feComposite in="SourceGraphic" in2="blur" operator="over" />
                </filter>
                <filter id="glowGold" x="-20%" y="-20%" width="140%" height="140%">
                  <feGaussianBlur stdDeviation="2.5" result="blur" />
                  <feComposite in="SourceGraphic" in2="blur" operator="over" />
                </filter>
                <filter id="glowCyan" x="-20%" y="-20%" width="140%" height="140%">
                  <feGaussianBlur stdDeviation="3" result="blur" />
                  <feComposite in="SourceGraphic" in2="blur" operator="over" />
                </filter>

                <marker id="arrowBlue" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="3.5" markerHeight="3.5" orient="auto-start-reverse">
                  <path d="M 0 0 L 6 3 L 0 6 z" fill="#3b82f6" />
                </marker>
                <marker id="arrowPurple" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="3.5" markerHeight="3.5" orient="auto-start-reverse">
                  <path d="M 0 0 L 6 3 L 0 6 z" fill="#a855f7" />
                </marker>
                <marker id="arrowSmallGreen" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="2.8" markerHeight="2.8" orient="auto-start-reverse">
                  <path d="M 0 0 L 6 3 L 0 6 z" fill="#10b981" />
                </marker>
                <marker id="arrowSmallAmber" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="2.8" markerHeight="2.8" orient="auto-start-reverse">
                  <path d="M 0 0 L 6 3 L 0 6 z" fill="#f59e0b" />
                </marker>
                <marker id="arrowSmallCyan" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="2.8" markerHeight="2.8" orient="auto-start-reverse">
                  <path d="M 0 0 L 6 3 L 0 6 z" fill="#06b6d4" />
                </marker>
              </defs>

              <rect width="100%" height="100%" fill="url(#blueprintGrid)" />

              {mode === "FIXED" ? (
                /* 2D SCHEMA FIXE */
                <g>
                  <line x1={O_fixed.x} y1={O_fixed.y} x2={O_fixed.x + 340} y2={O_fixed.y} stroke="#3b82f6" strokeWidth="1.8" markerEnd="url(#arrowBlue)" />
                  <line x1={O_fixed.x} y1={O_fixed.y} x2={O_fixed.x} y2={O_fixed.y - 150} stroke="#3b82f6" strokeWidth="1.8" markerEnd="url(#arrowBlue)" />
                  <text x={O_fixed.x + 328} y={O_fixed.y + 15} fill="#3b82f6" fontSize="13" fontWeight="bold" fontFamily="monospace">x</text>
                  <text x={O_fixed.x - 16} y={O_fixed.y - 138} fill="#3b82f6" fontSize="13" fontWeight="bold" fontFamily="monospace">y</text>
                  
                  <circle cx={O_fixed.x} cy={O_fixed.y} r="4" fill="#3b82f6" filter="url(#glowBlue)" />
                  <text x={O_fixed.x - 16} y={O_fixed.y + 15} fill="#60a5fa" fontSize="13" fontWeight="bold" fontFamily="monospace">O</text>

                  <line x1={O_fixed.x} y1={O_fixed.y} x2={O_fixed.x + 28} y2={O_fixed.y} stroke="#10b981" strokeWidth="1.8" markerEnd="url(#arrowSmallGreen)" />
                  <text x={O_fixed.x + 12} y={O_fixed.y + 15} fill="#10b981" fontSize="11" fontWeight="bold" fontFamily="monospace">i</text>

                  <line x1={O_fixed.x} y1={O_fixed.y} x2={O_fixed.x} y2={O_fixed.y - 28} stroke="#10b981" strokeWidth="1.8" markerEnd="url(#arrowSmallGreen)" />
                  <text x={O_fixed.x - 14} y={O_fixed.y - 10} fill="#10b981" fontSize="11" fontWeight="bold" fontFamily="monospace">j</text>

                  <circle cx={O1_fixed.x} cy={O1_fixed.y} r={R_fixed} fill="none" stroke="#a855f7" strokeWidth="2" opacity="0.9" />
                  <circle cx={O1_fixed.x} cy={O1_fixed.y} r="3.5" fill="#c084fc" />
                  <text x={O1_fixed.x - 12} y={O1_fixed.y + 16} fill="#c084fc" fontSize="12" fontWeight="bold" fontFamily="monospace">O1</text>

                  <line
                    x1={O_fixed.x}
                    y1={O_fixed.y}
                    x2={O1_fixed.x + 130 * ux1_fixed.x}
                    y2={O1_fixed.y + 130 * ux1_fixed.y}
                    stroke="#a855f7" strokeWidth="1.6" markerEnd="url(#arrowPurple)"
                  />
                  <text
                    x={O1_fixed.x + 138 * ux1_fixed.x}
                    y={O1_fixed.y + 138 * ux1_fixed.y + 4}
                    fill="#c084fc" fontSize="13" fontWeight="bold" fontFamily="monospace"
                  >
                    x1
                  </text>

                  <line
                    x1={O1_fixed.x - 35 * uy1_fixed.x}
                    y1={O1_fixed.y - 35 * uy1_fixed.y}
                    x2={O1_fixed.x + 110 * uy1_fixed.x}
                    y2={O1_fixed.y + 110 * uy1_fixed.y}
                    stroke="#a855f7" strokeWidth="1.6" strokeDasharray="4,2" markerEnd="url(#arrowPurple)"
                  />
                  <text
                    x={O1_fixed.x + 116 * uy1_fixed.x - 4}
                    y={O1_fixed.y + 116 * uy1_fixed.y}
                    fill="#c084fc" fontSize="13" fontWeight="bold" fontFamily="monospace"
                  >
                    y1
                  </text>

                  <line x1={O1_fixed.x} y1={O1_fixed.y} x2={O1_fixed.x + 24 * ux1_fixed.x} y2={O1_fixed.y + 24 * ux1_fixed.y} stroke="#10b981" strokeWidth="1.8" markerEnd="url(#arrowSmallGreen)" />
                  <text x={O1_fixed.x + 24 * ux1_fixed.x + 2} y={O1_fixed.y + 24 * ux1_fixed.y + 12} fill="#10b981" fontSize="10" fontWeight="bold" fontFamily="monospace">i1</text>

                  <line x1={O1_fixed.x} y1={O1_fixed.y} x2={O1_fixed.x + 24 * uy1_fixed.x} y2={O1_fixed.y + 24 * uy1_fixed.y} stroke="#10b981" strokeWidth="1.8" markerEnd="url(#arrowSmallGreen)" />
                  <text x={O1_fixed.x + 24 * uy1_fixed.x - 12} y={O1_fixed.y + 24 * uy1_fixed.y} fill="#10b981" fontSize="10" fontWeight="bold" fontFamily="monospace">j1</text>

                  <circle cx={A_fixed.x} cy={A_fixed.y} r="4" fill="#f59e0b" filter="url(#glowGold)" />
                  <text x={A_fixed.x + 8} y={A_fixed.y + 14} fill="#fbbf24" fontSize="13" fontWeight="bold" fontFamily="monospace">A</text>

                  <line x1={O1_fixed.x} y1={O1_fixed.y} x2={M_fixed.x} y2={M_fixed.y} stroke="#a855f7" strokeWidth="1.6" />

                  <circle cx={M_fixed.x} cy={M_fixed.y} r="5.5" fill="#38bdf8" filter="url(#glowCyan)" />
                  <text x={M_fixed.x + 8} y={M_fixed.y - 6} fill="#38bdf8" fontSize="14" fontWeight="black" fontFamily="monospace">M</text>

                  <path
                    d={`M ${O_fixed.x + 36},${O_fixed.y} A 36 36 0 0 0 ${O_fixed.x + 36 * Math.cos(thetaFixed)},${O_fixed.y - 36 * Math.sin(thetaFixed)}`}
                    fill="none" stroke="#f59e0b" strokeWidth="1.5" markerEnd="url(#arrowSmallAmber)"
                  />
                  <text x={O_fixed.x + 44 * Math.cos(thetaFixed / 2)} y={O_fixed.y - 44 * Math.sin(thetaFixed / 2)} fill="#fbbf24" fontSize="12" fontWeight="bold" fontFamily="monospace">θ</text>

                  <path
                    d={`M ${O1_fixed.x + 24 * ux1_fixed.x},${O1_fixed.y + 24 * ux1_fixed.y} A 24 24 0 0 0 ${O1_fixed.x + 24 * Math.cos(2 * thetaFixed)},${O1_fixed.y - 24 * Math.sin(2 * thetaFixed)}`}
                    fill="none" stroke="#f59e0b" strokeWidth="1.5" markerEnd="url(#arrowSmallAmber)"
                  />
                  <text x={O1_fixed.x + 32 * Math.cos(1.5 * thetaFixed)} y={O1_fixed.y - 32 * Math.sin(1.5 * thetaFixed)} fill="#fbbf24" fontSize="11" fontWeight="bold" fontFamily="monospace">θ</text>
                </g>
              ) : (
                /* 2D MOUVEMENT ANIMÉ */
                <g>
                  <line x1={O_anim.x - 120} y1={O_anim.y} x2={O_anim.x + 260} y2={O_anim.y} stroke="#3b82f6" strokeWidth="1.6" markerEnd="url(#arrowBlue)" />
                  <line x1={O_anim.x} y1={O_anim.y + 130} x2={O_anim.x} y2={O_anim.y - 130} stroke="#3b82f6" strokeWidth="1.6" markerEnd="url(#arrowBlue)" />
                  <text x={O_anim.x + 248} y={O_anim.y + 16} fill="#3b82f6" fontSize="13" fontWeight="bold" fontFamily="monospace">x</text>
                  <text x={O_anim.x - 16} y={O_anim.y - 118} fill="#3b82f6" fontSize="13" fontWeight="bold" fontFamily="monospace">y</text>
                  <circle cx={O_anim.x} cy={O_anim.y} r="4" fill="#3b82f6" filter="url(#glowBlue)" />
                  <text x={O_anim.x - 16} y={O_anim.y + 15} fill="#60a5fa" fontSize="13" fontWeight="bold" fontFamily="monospace">O</text>

                  {trail2DRef.current.length > 1 && (
                    <polyline
                      points={trail2DRef.current.map((p) => `${p.x},${p.y}`).join(" ")}
                      fill="none"
                      stroke="#fbbf24"
                      strokeWidth="2.5"
                      strokeDasharray="4,2"
                      filter="url(#glowGold)"
                    />
                  )}

                  <circle cx={O1_anim.x} cy={O1_anim.y} r={R_anim} fill="none" stroke="#a855f7" strokeWidth="1.8" />
                  <circle cx={O1_anim.x} cy={O1_anim.y} r="3.5" fill="#c084fc" />
                  <text x={O1_anim.x - 10} y={O1_anim.y + 15} fill="#c084fc" fontSize="11" fontWeight="bold" fontFamily="monospace">O1</text>

                  <line
                    x1={O1_anim.x - 30 * ux1_anim.x}
                    y1={O1_anim.y - 30 * ux1_anim.y}
                    x2={O1_anim.x + 100 * ux1_anim.x}
                    y2={O1_anim.y + 100 * ux1_anim.y}
                    stroke="#a855f7" strokeWidth="1.6" strokeDasharray="4,2" markerEnd="url(#arrowPurple)"
                  />
                  <line
                    x1={O1_anim.x - 30 * uy1_anim.x}
                    y1={O1_anim.y - 30 * uy1_anim.y}
                    x2={O1_anim.x + 85 * uy1_anim.x}
                    y2={O1_anim.y + 85 * uy1_anim.y}
                    stroke="#a855f7" strokeWidth="1.6" strokeDasharray="4,2" markerEnd="url(#arrowPurple)"
                  />
                  
                  <text
                    x={O1_anim.x + 108 * ux1_anim.x}
                    y={O1_anim.y + 108 * ux1_anim.y + 4}
                    fill="#c084fc" fontSize="12" fontWeight="bold" fontFamily="monospace"
                  >
                    x1
                  </text>

                  <text
                    x={O1_anim.x + 90 * uy1_anim.x - 4}
                    y={O1_anim.y + 90 * uy1_anim.y}
                    fill="#c084fc" fontSize="12" fontWeight="bold" fontFamily="monospace"
                  >
                    y1
                  </text>

                  <circle cx={A_anim.x} cy={A_anim.y} r="3.5" fill="#f59e0b" filter="url(#glowGold)" />
                  <text x={A_anim.x + 6} y={A_anim.y + 12} fill="#fbbf24" fontSize="12" fontWeight="bold" fontFamily="monospace">A</text>

                  <circle cx={M_anim.x} cy={M_anim.y} r="5" fill="#38bdf8" filter="url(#glowCyan)" />
                  <text x={M_anim.x + 8} y={M_anim.y - 5} fill="#38bdf8" fontSize="13" fontWeight="black" fontFamily="monospace">M</text>

                  <line x1={O_anim.x} y1={O_anim.y} x2={O1_anim.x} y2={O1_anim.y} stroke="#f59e0b" strokeWidth="2.0" markerEnd="url(#arrowSmallAmber)" />
                  <line x1={O1_anim.x} y1={O1_anim.y} x2={M_anim.x} y2={M_anim.y} stroke="#10b981" strokeWidth="2.0" markerEnd="url(#arrowSmallGreen)" />
                  <line x1={O_anim.x} y1={O_anim.y} x2={M_anim.x} y2={M_anim.y} stroke="#06b6d4" strokeWidth="2.2" markerEnd="url(#arrowSmallCyan)" filter="url(#glowCyan)" />
                </g>
              )}
            </svg>
          </div>

          {/* Controls Bar for Animated Mode */}
          {mode === "ANIMATED" && (
            <div className="mt-2 flex flex-wrap items-center justify-between gap-2 p-2 rounded-xl bg-slate-900 border border-slate-800">
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setIsPlaying(!isPlaying)}
                  className="flex items-center gap-1.5 px-3 py-1 rounded-lg bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold text-xs transition-all shadow-md"
                >
                  {isPlaying ? <Pause className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5" />}
                  <span>{isPlaying ? "Pause" : "Animer"}</span>
                </button>

                <button
                  onClick={handleReset}
                  className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold text-xs transition-all"
                >
                  <RotateCcw className="w-3.5 h-3.5" />
                  <span>Réinitialiser</span>
                </button>
              </div>

              <div className="flex flex-wrap items-center gap-3 text-xs font-mono text-slate-300">
                <div className="flex items-center gap-1.5">
                  <span>Vitesse angulaire <LatexMath math="\omega" />:</span>
                  <input
                    type="range"
                    min="0.4"
                    max="3.0"
                    step="0.2"
                    value={omega}
                    onChange={(e) => setOmega(parseFloat(e.target.value))}
                    className="w-16 sm:w-20 h-1.5 accent-amber-500 cursor-pointer rounded-lg bg-slate-800"
                  />
                  <span className="font-bold text-amber-400">{omega.toFixed(1)} rad/s</span>
                </div>
              </div>
            </div>
          )}

          {/* HIDDEN SOLUTION DRAWER AT THE VERY BOTTOM */}
          <div className="mt-3 border border-slate-800 rounded-xl bg-slate-950 overflow-hidden shadow-lg">
            <button
              onClick={() => setShowSolution(!showSolution)}
              className="w-full flex items-center justify-between p-3 bg-indigo-600/20 hover:bg-indigo-600/30 text-indigo-300 font-bold text-xs sm:text-sm border-b border-slate-800/80 transition-all"
            >
              <span className="flex items-center gap-2">
                <BookOpen className="w-4 h-4 text-indigo-400" />
                <span>{showSolution ? "Masquer la Correction" : "Afficher la Solution Détaillée 📑"}</span>
              </span>
              {showSolution ? <ChevronUp className="w-4 h-4 text-indigo-400" /> : <ChevronDown className="w-4 h-4 text-indigo-400" />}
            </button>

            {showSolution && (
              <div className="p-3.5 space-y-3 text-xs sm:text-sm font-mono text-slate-200 leading-relaxed animate-in fade-in duration-200">
                {/* Step 1 */}
                <div className="p-3 rounded-xl bg-slate-900/90 border border-slate-800 space-y-1">
                  <h4 className="font-bold text-cyan-400 flex items-center gap-1.5 text-xs sm:text-sm">
                    <CheckCircle2 className="w-4 h-4 text-cyan-400" />
                    <span>1. Expression des Vecteurs Position :</span>
                  </h4>
                  <p>• Centre mobile : <LatexMath math="\vec{OO}_1 = R \vec{i}_1 = R\cos(\omega t)\vec{i} + R\sin(\omega t)\vec{j}" /></p>
                  <p>• Position relative de <LatexMath math="M" /> dans <LatexMath math="\mathcal{R}_1" /> : <LatexMath math="\vec{O_1 M} = R\cos(\omega t)\vec{i}_1 + R\sin(\omega t)\vec{j}_1" /></p>
                </div>

                {/* Step 2 */}
                <div className="p-3 rounded-xl bg-slate-900/90 border border-slate-800 space-y-1">
                  <h4 className="font-bold text-emerald-400 flex items-center gap-1.5 text-xs sm:text-sm">
                    <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                    <span>2. Vitesse Relative <LatexMath math="\vec{V}_r(M)" /> et Vitesse d'Entraînement <LatexMath math="\vec{V}_e(M)" /> :</span>
                  </h4>
                  <p>Dérivée par rapport au temps dans le repère mobile <LatexMath math="\mathcal{R}_1" /> :</p>
                  <div className="p-2 rounded-lg bg-slate-950 border border-slate-800 text-emerald-300 font-bold text-center">
                    <LatexMath math="\vec{V}_r(M) = \left[\frac{d\vec{O_1 M}}{dt}\right]_{\mathcal{R}_1} = -R\omega\sin(\omega t)\vec{i}_1 + R\omega\cos(\omega t)\vec{j}_1" />
                  </div>
                  <p>Vitesse d'entraînement :</p>
                  <div className="p-2 rounded-lg bg-slate-950 border border-slate-800 text-amber-300 font-bold text-center">
                    <LatexMath math="\vec{V}_e(M) = -R\omega\sin(\omega t)\vec{i}_1 + R\omega(1 + \cos\omega t)\vec{j}_1" />
                  </div>
                </div>

                {/* Step 3 */}
                <div className="p-3 rounded-xl bg-slate-900/90 border border-slate-800 space-y-1">
                  <h4 className="font-bold text-rose-400 flex items-center gap-1.5 text-xs sm:text-sm">
                    <CheckCircle2 className="w-4 h-4 text-rose-400" />
                    <span>3. Accélération de Coriolis <LatexMath math="\vec{\gamma}_c(M)" /> :</span>
                  </h4>
                  <p><LatexMath math="\vec{\gamma}_c(M) = 2 \vec{\Omega} \wedge \vec{V}_r(M) = 2(\omega\vec{k}) \wedge [-R\omega\sin(\omega t)\vec{i}_1 + R\omega\cos(\omega t)\vec{j}_1]" /></p>
                  <div className="p-2 rounded-lg bg-rose-500/20 border border-rose-500/50 text-rose-300 font-bold text-center">
                    <LatexMath math="\vec{\gamma}_c(M) = -2R\omega^2\cos(\omega t)\vec{i}_1 - 2R\omega^2\sin(\omega t)\vec{j}_1 = -2\omega^2 \vec{O_1 M}" />
                  </div>
                </div>

                {/* Step 4 */}
                <div className="p-3 rounded-xl bg-slate-900/90 border border-slate-800 space-y-1">
                  <h4 className="font-bold text-purple-400 flex items-center gap-1.5 text-xs sm:text-sm">
                    <CheckCircle2 className="w-4 h-4 text-purple-400" />
                    <span>4. Trajectoire Absolue (Cardioïde) :</span>
                  </h4>
                  <p>Dans la base fixe <LatexMath math="(\vec{i}, \vec{j})" /> :</p>
                  <p><LatexMath math="x(t) = R\cos(\omega t) + R\cos(2\omega t) \,,\quad y(t) = R\sin(\omega t) + R\sin(2\omega t)" /></p>
                  <p className="text-amber-300 font-bold">La courbe engendrée par le point $M$ est une Cardioïde.</p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { Sparkles, Play, Pause, Activity } from "lucide-react";
import LatexMath from "@/components/ui/LatexMath";

// High-Resolution crisp mathematical vector labels - Scaled DOWN for elegance
function createVectorSprite(base: string, sub: string = "", colorHex: string = "#ffffff") {
  const canvas = document.createElement("canvas");
  canvas.width = 256;
  canvas.height = 128;
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.fillStyle = colorHex;
    ctx.shadowColor = colorHex;
    ctx.shadowBlur = 8;
    
    const baseFontSize = 72;
    const subFontSize = 46;
    
    ctx.font = `italic bold ${baseFontSize}px 'Times New Roman', serif`;
    const baseWidth = ctx.measureText(base).width;
    
    ctx.font = `bold ${subFontSize}px 'Times New Roman', serif`;
    const subWidth = sub ? ctx.measureText(sub).width : 0;
    
    const totalWidth = baseWidth + subWidth;
    const startX = 128 - totalWidth / 2;
    
    ctx.font = `italic bold ${baseFontSize}px 'Times New Roman', serif`;
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    ctx.fillText(base, startX, 64);
    
    if (sub) {
      ctx.font = `bold ${subFontSize}px 'Times New Roman', serif`;
      ctx.fillText(sub, startX + baseWidth, 82);
    }
    
    const arrowY = 20;
    ctx.beginPath();
    ctx.moveTo(startX, arrowY);
    ctx.lineTo(startX + totalWidth, arrowY);
    ctx.lineTo(startX + totalWidth - 10, arrowY - 8);
    ctx.moveTo(startX + totalWidth, arrowY);
    ctx.lineTo(startX + totalWidth - 10, arrowY + 8);
    ctx.strokeStyle = colorHex;
    ctx.lineWidth = 6;
    ctx.stroke();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  const spriteMat = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false });
  const sprite = new THREE.Sprite(spriteMat);
  // CRITICAL: Made extremely small and delicate for a premium non-cluttered look
  sprite.scale.set(0.35, 0.175, 1);
  return sprite;
}

export default function RelativeMotion3DCanvas() {
  const mountRef = useRef<HTMLDivElement>(null);
  
  const [omega, setOmega] = useState<number>(1.5); 
  const [vRel, setVRel] = useState<number>(2.0); 
  const [isPlaying, setIsPlaying] = useState<boolean>(true);

  const animFrameRef = useRef<number | null>(null);

  useEffect(() => {
    const container = mountRef.current;
    if (!container) return;
    container.innerHTML = "";

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x020617); 
    scene.fog = new THREE.Fog(0x020617, 4, 15);

    const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 1000);
    // Pulled camera back for breathing room
    camera.position.set(4.5, 3.5, 6.0);

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.domElement.style.width = '100%';
    renderer.domElement.style.height = '100%';
    renderer.domElement.style.display = 'block';
    container.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.enablePan = false; 
    controls.enableZoom = false; 
    controls.target.set(0.0, 0.5, 0.0);
    controls.maxPolarAngle = Math.PI / 2 + 0.1;
    controls.update();

    const updateSize = () => {
      if (!container) return;
      const width = container.clientWidth;
      const height = container.clientHeight;
      camera.aspect = width / height;
      camera.fov = width < 640 ? 50 : 40;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    };

    scene.add(new THREE.AmbientLight(0xffffff, 1.2));
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
    dirLight.position.set(4, 10, 6);
    scene.add(dirLight);

    const gridR = new THREE.GridHelper(10, 20, 0x1e293b, 0x0f172a);
    gridR.position.y = -0.5;
    scene.add(gridR);

    // --- REPERE FIXE R(O, x, y, z) ---
    const fixedAxes = new THREE.Group();
    fixedAxes.add(
      new THREE.ArrowHelper(new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 0, 0), 2.5, 0x334155, 0.1, 0.05),
      new THREE.ArrowHelper(new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0, 0), 2.5, 0x334155, 0.1, 0.05),
      new THREE.ArrowHelper(new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, 0), 2.5, 0x334155, 0.1, 0.05)
    );
    scene.add(fixedAxes);
    // REMOVED clutter labels O, x, y, z 

    // --- REPERE MOBILE R1(O1, x1, y1, z1) ---
    const mobileFrameGroup = new THREE.Group();
    scene.add(mobileFrameGroup);

    const mobileX = new THREE.ArrowHelper(new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 0, 0), 2.2, 0x7e22ce, 0.12, 0.06);
    const mobileY = new THREE.ArrowHelper(new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0, 0), 2.4, 0xb45309, 0.12, 0.06);
    const mobileZ = new THREE.ArrowHelper(new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, 0), 2.2, 0x0891b2, 0.12, 0.06);
    mobileFrameGroup.add(mobileX, mobileY, mobileZ);
    // REMOVED clutter labels x1, z1

    const labelOmega = createVectorSprite("Ω", "", "#fbbf24");
    labelOmega.position.set(0, 2.6, 0);
    mobileFrameGroup.add(labelOmega);

    // --- PARTICLE M ---
    const pointMGeo = new THREE.SphereGeometry(0.12, 32, 32);
    const pointMMat = new THREE.MeshStandardMaterial({ color: 0x38bdf8, emissive: 0x0ea5e9, emissiveIntensity: 1.2, roughness: 0.1 });
    const pointMMesh = new THREE.Mesh(pointMGeo, pointMMat);
    scene.add(pointMMesh);
    // REMOVED clutter label M

    // --- COMPOSITION VECTORS ---
    // Made arrows slightly thinner for elegance
    const vrArrow = new THREE.ArrowHelper(new THREE.Vector3(1,0,0), new THREE.Vector3(0,0,0), 1, 0x10b981, 0.12, 0.06);
    const veArrow = new THREE.ArrowHelper(new THREE.Vector3(1,0,0), new THREE.Vector3(0,0,0), 1, 0xf59e0b, 0.12, 0.06);
    const vaArrow = new THREE.ArrowHelper(new THREE.Vector3(1,0,0), new THREE.Vector3(0,0,0), 1, 0x06b6d4, 0.14, 0.08);
    const acArrow = new THREE.ArrowHelper(new THREE.Vector3(1,0,0), new THREE.Vector3(0,0,0), 1, 0xf43f5e, 0.14, 0.08);
    scene.add(vrArrow, veArrow, vaArrow, acArrow);

    const labelVr = createVectorSprite("V", "r", "#34d399");
    const labelVe = createVectorSprite("V", "e", "#fbbf24");
    const labelVa = createVectorSprite("V", "a", "#22d3ee");
    const labelAc = createVectorSprite("γ", "c", "#fb7185");
    scene.add(labelVr, labelVe, labelVa, labelAc);

    const resizeObserver = new ResizeObserver(updateSize);
    resizeObserver.observe(container);

    let time = 0;
    let lastTime = performance.now();

    const animate = (now: number) => {
      const delta = (now - lastTime) / 1000;
      lastTime = now;
      if (isPlaying) time += delta;

      const thetaR1 = omega * time;
      mobileFrameGroup.rotation.y = thetaR1;

      // Particle oscillation
      const rM = 1.0 + 0.6 * Math.sin(vRel * 0.8 * time); 
      const vrM = 0.6 * (vRel * 0.8) * Math.cos(vRel * 0.8 * time);

      const posLocal = new THREE.Vector3(rM, 0, 0);
      const posWorld = posLocal.clone().applyAxisAngle(new THREE.Vector3(0, 1, 0), thetaR1);
      
      pointMMesh.position.copy(posWorld);

      const vrLocal = new THREE.Vector3(vrM, 0, 0);
      const vrWorld = vrLocal.clone().applyAxisAngle(new THREE.Vector3(0, 1, 0), thetaR1);
      
      const omegaVec = new THREE.Vector3(0, omega, 0);
      const veWorld = new THREE.Vector3().crossVectors(omegaVec, posWorld);
      const vaWorld = new THREE.Vector3().addVectors(vrWorld, veWorld);
      
      const acWorld = new THREE.Vector3().crossVectors(omegaVec, vrWorld).multiplyScalar(2);

      // Delicate vector scaling
      const visualScale = 0.6; 

      vrArrow.position.copy(posWorld);
      if (vrWorld.length() > 0.05) {
        const len = vrWorld.length() * visualScale;
        const dir = vrWorld.clone().normalize();
        vrArrow.setDirection(dir);
        vrArrow.setLength(len, 0.12, 0.06);
        vrArrow.visible = true; labelVr.visible = true;
        // Small elegant offset
        labelVr.position.copy(posWorld.clone().add(dir.multiplyScalar(len + 0.1)).add(new THREE.Vector3(0, 0.1, 0)));
      } else {
        vrArrow.visible = false; labelVr.visible = false;
      }

      veArrow.position.copy(posWorld);
      if (veWorld.length() > 0.05) {
        const len = veWorld.length() * visualScale * 0.7;
        const dir = veWorld.clone().normalize();
        veArrow.setDirection(dir);
        veArrow.setLength(len, 0.12, 0.06);
        veArrow.visible = true; labelVe.visible = true;
        labelVe.position.copy(posWorld.clone().add(dir.multiplyScalar(len + 0.1)).add(new THREE.Vector3(0, -0.1, 0)));
      } else {
        veArrow.visible = false; labelVe.visible = false;
      }

      vaArrow.position.copy(posWorld);
      if (vaWorld.length() > 0.05) {
        const len = vaWorld.length() * visualScale * 0.8;
        const dir = vaWorld.clone().normalize();
        vaArrow.setDirection(dir);
        vaArrow.setLength(len, 0.14, 0.08);
        vaArrow.visible = true; labelVa.visible = true;
        labelVa.position.copy(posWorld.clone().add(dir.multiplyScalar(len + 0.1)).add(new THREE.Vector3(0.05, 0, 0)));
      } else {
        vaArrow.visible = false; labelVa.visible = false;
      }

      acArrow.position.copy(posWorld);
      if (acWorld.length() > 0.05) {
        const len = Math.min(acWorld.length() * 0.3, 1.8);
        const dir = acWorld.clone().normalize();
        acArrow.setDirection(dir);
        acArrow.setLength(len, 0.14, 0.08);
        acArrow.visible = true; labelAc.visible = true;
        labelAc.position.copy(posWorld.clone().add(dir.multiplyScalar(len + 0.1)).add(new THREE.Vector3(-0.05, 0.1, 0)));
      } else {
        acArrow.visible = false; labelAc.visible = false;
      }

      controls.target.set(0, 0.5, 0); 
      controls.update();

      renderer.render(scene, camera);
      if (isInViewRef.current) animFrameRef.current = requestAnimationFrame(animate);
    };

    updateSize();

    const isInViewRef = { current: false };
    const intersectionObserver = new IntersectionObserver(
      ([entry]) => {
        isInViewRef.current = entry.isIntersecting;
        if (isInViewRef.current) animFrameRef.current = requestAnimationFrame(animate);
      },
      { threshold: 0.05 }
    );
    intersectionObserver.observe(container);

    return () => {
      if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
      intersectionObserver.disconnect();
      controls.dispose();
      resizeObserver.disconnect();
      if (container.contains(renderer.domElement)) container.removeChild(renderer.domElement);
    };
  }, [omega, vRel, isPlaying]);

  return (
    <div className="p-3 sm:p-4 rounded-2xl sm:rounded-3xl bg-slate-950/80 border border-slate-800 text-white shadow-xl max-w-full overflow-hidden">
      
      <div className="flex flex-wrap items-center justify-between gap-2.5 mb-2">
        <div>
          <h3 className="text-[11px] sm:text-sm font-bold text-amber-400 flex items-center gap-1.5">
            <Sparkles className="w-3.5 h-3.5 text-amber-400 flex-shrink-0" />
            <span>Simulateur Interactif : Repère <LatexMath math="\mathcal{R}" /> & Mobile <LatexMath math="\mathcal{R}_1" /></span>
          </h3>
          <p className="text-[9px] sm:text-[10px] text-slate-400">
            Visualisation 3D de la composition <LatexMath math="\vec{V}_a = \vec{V}_r + \vec{V}_e" />
          </p>
        </div>

        <div className="flex items-center gap-1.5">
          <button
            onClick={() => setIsPlaying(!isPlaying)}
            className="flex items-center gap-1 px-2.5 py-1 rounded-md bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold text-[10px] transition-all"
          >
            {isPlaying ? <Pause className="w-3 h-3" /> : <Play className="w-3 h-3" />}
            <span>{isPlaying ? "Pause" : "Animer"}</span>
          </button>
        </div>
      </div>

      <div className="relative rounded-xl overflow-hidden border border-slate-800 bg-slate-950 h-[280px] sm:h-[350px] w-full flex items-center justify-center">
        <div ref={mountRef} className="w-full h-full block cursor-grab active:cursor-grabbing" />
        <div className="absolute bottom-2 right-2 bg-slate-900/90 backdrop-blur-sm px-2 py-0.5 rounded border border-slate-700 text-[9px] text-slate-300 pointer-events-none">
          👆 Glissez pour tourner la caméra
        </div>
      </div>

      <div className="mt-2.5 p-2 rounded-lg bg-slate-900/90 border border-slate-800 text-xs font-mono">
        <div className="flex items-center gap-1.5 text-amber-400 font-bold mb-1.5 text-[10px] sm:text-xs">
          <Activity className="w-3.5 h-3.5" />
          <span>Composition des Vitesses & Coriolis :</span>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-1.5 text-[9px] sm:text-[10px]">
          <div className="flex items-center gap-1.5 p-1.5 rounded bg-slate-950 border border-slate-800">
            <span className="w-2 h-2 rounded-full bg-emerald-400 shrink-0" />
            <div className="leading-tight">
              <span className="text-slate-400 block text-[8px]">Vitesse Relative</span>
              <span className="text-emerald-400 font-bold"><LatexMath math="\vec{V}_r" /></span>
            </div>
          </div>
          <div className="flex items-center gap-1.5 p-1.5 rounded bg-slate-950 border border-slate-800">
            <span className="w-2 h-2 rounded-full bg-amber-400 shrink-0" />
            <div className="leading-tight">
              <span className="text-slate-400 block text-[8px]">Vitesse d'Entraînement</span>
              <span className="text-amber-400 font-bold"><LatexMath math="\vec{V}_e" /></span>
            </div>
          </div>
          <div className="flex items-center gap-1.5 p-1.5 rounded bg-slate-950 border border-slate-800">
            <span className="w-2 h-2 rounded-full bg-cyan-400 shrink-0" />
            <div className="leading-tight">
              <span className="text-slate-400 block text-[8px]">Vitesse Absolue</span>
              <span className="text-cyan-400 font-bold"><LatexMath math="\vec{V}_a" /></span>
            </div>
          </div>
          <div className="flex items-center gap-1.5 p-1.5 rounded bg-slate-950 border border-slate-800">
            <span className="w-2 h-2 rounded-full bg-rose-400 shrink-0" />
            <div className="leading-tight">
              <span className="text-slate-400 block text-[8px]">Accélération Coriolis</span>
              <span className="text-rose-400 font-bold"><LatexMath math="\vec{\gamma}_c" /></span>
            </div>
          </div>
        </div>
      </div>

      <div className="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-2 p-2 rounded-lg bg-slate-900 border border-slate-800 text-[10px] sm:text-[11px] font-mono">
        <div className="flex flex-col gap-1">
          <div className="flex justify-between text-slate-300">
            <span>Rotation <LatexMath math="\Omega" /> :</span>
            <span className="text-amber-400 font-bold">{omega.toFixed(1)} rad/s</span>
          </div>
          <input
            type="range" min="0" max="4" step="0.2" value={omega}
            onChange={(e) => setOmega(parseFloat(e.target.value))}
            className="w-full accent-amber-500 cursor-pointer h-1.5"
          />
        </div>
        <div className="flex flex-col gap-1">
          <div className="flex justify-between text-slate-300">
            <span>Vitesse <LatexMath math="V_r" /> :</span>
            <span className="text-emerald-400 font-bold">{vRel.toFixed(1)} m/s</span>
          </div>
          <input
            type="range" min="0.5" max="5" step="0.2" value={vRel}
            onChange={(e) => setVRel(parseFloat(e.target.value))}
            className="w-full accent-emerald-500 cursor-pointer h-1.5"
          />
        </div>
      </div>

    </div>
  );
}

